const raw = $json.content || $json.text || $json.message?.content;

let data;

try {
  if (typeof raw === "object" && raw !== null) {
    data = raw;
  } else if (typeof raw === "string") {
    let cleaned = raw.trim();
    cleaned = cleaned
      .replace(/^\s*```(json)?/i, "")
      .replace(/```\s*$/i, "")
      .trim();

    try {
      data = JSON.parse(cleaned);
    } catch (err) {
      // Cleanup pass 2: find first { and last }
      const firstBrace = cleaned.indexOf('{');
      const lastBrace = cleaned.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
        const extracted = cleaned.substring(firstBrace, lastBrace + 1);
        try {
          data = JSON.parse(extracted);
        } catch (err2) {
          throw new Error("RESUME_PARSE_FAILED: " + raw.substring(0, 300));
        }
      } else {
        throw new Error("RESUME_PARSE_FAILED: " + raw.substring(0, 300));
      }
    }
  } else {
    throw new Error("RESUME_PARSE_FAILED: Output was empty or unsupported.");
  }
} catch (error) {
  if (error.message && error.message.startsWith("RESUME_PARSE_FAILED")) {
    throw error;
  }
  throw new Error("RESUME_PARSE_FAILED: " + (typeof raw === 'string' ? raw.substring(0, 300) : "unknown error"));
}

if (!data) {
  throw new Error("RESUME_PARSE_FAILED: Parsed data is empty");
}

if (!data.candidate) {
  data = { candidate: data };
}

const candidate = data.candidate;
candidate.location = candidate.location || {};
if (typeof candidate.location === "string") {
  candidate.location = { raw: candidate.location };
}

// JSON Schema check
const missing = [];
if (!candidate.name) missing.push("name");
// Collect skill strings from every shape the profile model has actually
// produced. Three distinct shapes have been observed live:
//   1. candidate.skills = ["React", ...]                       (flat array)
//   2. candidate.skills = [] with siblings populated
//      (programming_languages / frameworks / tools / domains)
//   3. candidate.skills = { programming_languages: [...], frameworks: [...] }
//      (nested object, siblings absent)
// Requiring one exact shape failed whole runs on the model's formatting whim.
// This does NOT relax the requirement that at least one skill exist.
function collectSkillStrings(value, depth) {
  if (depth > 3 || value == null) return [];
  if (typeof value === 'string') return value.trim() ? [value.trim()] : [];
  if (Array.isArray(value)) {
    return value.flatMap((v) => collectSkillStrings(v, depth + 1));
  }
  if (typeof value === 'object') {
    return Object.values(value).flatMap((v) => collectSkillStrings(v, depth + 1));
  }
  return [];
}

function gatherCandidateSkills(cand) {
  const sources = [
    cand.skills,
    cand.programming_languages,
    cand.frameworks,
    cand.tools,
    cand.domains,
  ];
  const out = [];
  const seen = new Set();
  for (const s of sources) {
    for (const str of collectSkillStrings(s, 0)) {
      const key = str.toLowerCase();
      if (!seen.has(key)) { seen.add(key); out.push(str); }
    }
  }
  return out;
}

const skillUnion = gatherCandidateSkills(candidate);

if (skillUnion.length === 0) missing.push("skills");
if (!candidate.experience_level) missing.push("experience_level");
if (!candidate.location || !candidate.location.state) missing.push("location.state");
if (!candidate.location || !candidate.location.country) missing.push("location.country");

if (missing.length > 0) {
  throw new Error("RESUME_PARSE_INCOMPLETE: Missing required fields: " + missing.join(", "));
}

return [
  {
    json: data
  }
];

