parameters.jsCode:
let item = $json.data || $json;
if (typeof item !== 'object' || item === null) {
  item = { error: "Invalid opportunity data", raw: item };
}
return { json: item };

// ============================================================
// OPPORTUNITY RADAR — MULTI-SOURCE INTERNET SEARCH PLANNER V3
// ============================================================
// Purpose:
// 1. Search the OPEN INTERNET — NOT Opportunity Radar database
// 2. Prioritise official company career pages / ATS platforms
// 3. Focus on jobs + internships
// 4. Prefer candidate's city/state/country
// 5. International opportunities should preferably be remote
// 6. Generate diversified search queries
// ============================================================


// ------------------------------------------------------------
// 1. INPUT
// ------------------------------------------------------------

const input = $input.first().json;
const candidate = input.candidate || input;


// ------------------------------------------------------------
// 2. HELPER FUNCTIONS
// ------------------------------------------------------------

function clean(value) {
  return typeof value === "string" ? value.trim() : "";
}

function uniqueStrings(values) {
  return [
    ...new Set(
      values
        .filter(Boolean)
        .map(v => String(v).trim())
        .filter(Boolean)
    )
  ];
}

function normaliseRole(role) {
  return clean(role)
    .replace(/\s+/g, " ")
    .trim();
}


// ------------------------------------------------------------
// 3. CANDIDATE DATA
// ------------------------------------------------------------

const education = candidate.education || {};

const skills = uniqueStrings(
  Array.isArray(candidate.skills)
    ? candidate.skills
    : []
);

const programmingLanguages = uniqueStrings(
  candidate.programming_languages ||
  candidate.programmingLanguages ||
  []
);

const frameworks = uniqueStrings(
  candidate.frameworks || []
);

// Collect skill strings from every shape the profile model has actually
// produced. Three distinct shapes have been observed live:
//   1. candidate.skills = ["React", ...]                       (flat array)
//   2. candidate.skills = [] with siblings populated
//      (programming_languages / frameworks / tools / domains)
//   3. candidate.skills = { programming_languages: [...], frameworks: [...] }
//      (nested object, siblings absent)
// Requiring one exact shape failed whole runs on the model's formatting whim.
// This does NOT relax the requirement that at least one skill exist.
function collectSkillStrings(value, depth) {
  if (depth > 3 || value == null) return [];
  if (typeof value === 'string') return value.trim() ? [value.trim()] : [];
  if (Array.isArray(value)) {
    return value.flatMap((v) => collectSkillStrings(v, depth + 1));
  }
  if (typeof value === 'object') {
    return Object.values(value).flatMap((v) => collectSkillStrings(v, depth + 1));
  }
  return [];
}

function gatherCandidateSkills(cand) {
  const sources = [
    cand.skills,
    cand.programming_languages,
    cand.frameworks,
    cand.tools,
    cand.domains,
  ];
  const out = [];
  const seen = new Set();
  for (const s of sources) {
    for (const str of collectSkillStrings(s, 0)) {
      const key = str.toLowerCase();
      if (!seen.has(key)) { seen.add(key); out.push(str); }
    }
  }
  return out;
}

const allTechnicalSkills = uniqueStrings(gatherCandidateSkills(candidate));


// ------------------------------------------------------------
// 4. TARGET ROLE + OPPORTUNITY TYPE  (via search-planner:4200)
// ------------------------------------------------------------
// Opportunity type follows the candidate's academic year rather than the
// old assumption that every candidate wants an internship (F2/F3).
// search-planner owns that logic (search-planner/src/opportunity-type.js);
// it is deliberately NOT duplicated here.
//
// /search-plan/preview is the stateless endpoint. /search-plan/build cannot
// be used: search_plans.candidate_id is a FK into candidates(id) and this
// pipeline never persists a candidate row.
// ------------------------------------------------------------

function toCareerStage(value) {
  const v = String(value || "").toLowerCase();
  if (/senior|lead|principal|staff/.test(v)) return "senior";
  if (/mid/.test(v)) return "mid-career";
  if (/entry|early|junior|fresher|graduate|new.?grad/.test(v)) return "early-career";
  if (/student|intern|undergrad/.test(v)) return "student";
  return "student";
}

const careerIntel   = input.career_intelligence || {};
const searchProfile = input.search_profile || {};

// `education` may be a single object (the build-profile schema's declared
// shape) or an array when the resume lists several degrees. Handle both, and
// use the MOST RECENT graduation year — otherwise a graduate with a prior
// degree silently falls back to careerStage and gets routed to internships.
const educationEntries = Array.isArray(candidate.education)
  ? candidate.education
  : (education && typeof education === "object" ? [education] : []);

const graduationYear = educationEntries
  .map((e) => e && (e.graduation_year ?? e.graduationYear ?? e.endYear))
  .map((y) => (typeof y === "string" ? parseInt(y.slice(0, 4), 10) : y))
  .filter((y) => Number.isInteger(y))
  .reduce((latest, y) => (latest === null || y > latest ? y : latest), null);

const cip = {
  meta: {
    schemaVersion:     "2.0.0",
    modelVersion:      "n8n-inline-adapter",
    builtAt:           new Date().toISOString(),
    resumeHash:        "",
    overallConfidence: 0.5
  },
  literal: {
    fullName:  candidate.name || null,
    rawSkills: allTechnicalSkills,
    education: [
      {
        institution: education.institution || "Unknown",
        degree:      education.degree || null,
        field:       education.field || null,
        startYear:   null,
        endYear:     graduationYear,
        gpa:         null
      }
    ],
    experience: (candidate.experience || [])
      .map((e) => ({
        company:      e.organization || e.company || "Unknown",
        title:        e.role || e.title || "",
        startDate:    null,
        endDate:      null,
        description:  e.description || null,
        technologies: e.technologies || []
      }))
      .filter((e) => e.title),
    projects:           [],
    preferredLocations: []
  },
  inferred: {
    careerStage: {
      value:      toCareerStage(candidate.experience_level || searchProfile.candidate_stage),
      confidence: 0.7,
      evidence:   ["resume"]
    },
    canonicalSkills: uniqueStrings(candidate.domains || []).map((d) => ({
      canonical: d, raw: d, category: "domain", confidence: 0.7
    })),
    inferredRoles: [],
    careerDirection: {
      primary: (careerIntel.primary_roles || searchProfile.target_roles || [])[0] || null,
      adjacent: uniqueStrings([
        ...(careerIntel.primary_roles || []).slice(1),
        ...(careerIntel.secondary_roles || [])
      ]),
      confidence: 0.7,
      evidence:   ["resume"]
    },
    searchKeywords:    uniqueStrings(careerIntel.search_keywords || []),
    searchIntent:      "Discovery via Opportunity Radar pipeline.",
    workAuthorization: { value: "unknown", confidence: 0.1, evidence: ["not stated"] },
    openToRelocation:  { value: null,      confidence: 0.1, evidence: ["not stated"] }
  }
};

let plan;
try {
  plan = await this.helpers.httpRequest({
    method:  "POST",
    url:     "http://localhost:4200/search-plan/preview",
    headers: { "Content-Type": "application/json" },
    body:    { cip },
    json:    true
  });
} catch (error) {
  // Deliberately NOT swallowed. Without the planner every candidate would
  // silently fall back to internship-biased search — the exact bug this
  // wiring exists to fix. Failing loudly is correct here.
  throw new Error(
    "SEARCH_PLANNER_UNAVAILABLE: could not reach search-planner:4200 " +
    "(/search-plan/preview). Start it before running the pipeline. " +
    "Underlying error: " + (error.message || error)
  );
}

// Internships only. The planner still reports student status so a non-student
// can be surfaced honestly downstream, but it no longer selects a search type.
const opportunityType     = plan.opportunityType;          // always "internship"
const opportunityFallback = plan.opportunityTypeFallback || [];
const studentStatus       = plan.studentStatus || "unknown";
const isCurrentStudent    = plan.isCurrentStudent !== false;
const wantsInternship     = true;
const stageTerm           = "internship";

// search-planner's titleVariants are authoritative: they are already expanded
// for the derived opportunity type and have any pre-baked stage qualifier
// stripped. The upstream profile's role names are NOT merged in — the
// build-profile prompt bakes "Intern" into them ("Frontend Developer Intern"),
// which would reintroduce F2 for job-seeking candidates.
let targetRoles = uniqueStrings(plan.titleVariants || []);

if (targetRoles.length === 0) {
  targetRoles = ["Software Engineer"];
}

// Keep search explosion controlled.
targetRoles = uniqueStrings(targetRoles.map(normaliseRole)).slice(0, 4);


// ------------------------------------------------------------
// 5. LOCATION RESOLUTION
// ------------------------------------------------------------

const locationObject =
  candidate.location ||
  candidate.address ||
  candidate.contact?.location ||
  candidate.contact_info?.location ||
  candidate.personal_info?.location ||
  candidate.personalInfo?.location ||
  input.location ||
  {};

let city = clean(
  locationObject?.city ||
  candidate.city ||
  candidate.contact?.city ||
  candidate.contact_info?.city ||
  candidate.personal_info?.city ||
  candidate.personalInfo?.city ||
  input.city
);

let state = clean(
  locationObject?.state ||
  locationObject?.state_province ||
  locationObject?.region ||
  candidate.state ||
  candidate.contact?.state ||
  candidate.contact_info?.state ||
  candidate.personal_info?.state ||
  candidate.personalInfo?.state ||
  input.state
);

let country = clean(
  locationObject?.country ||
  candidate.country ||
  candidate.contact?.country ||
  candidate.contact_info?.country ||
  candidate.personal_info?.country ||
  candidate.personalInfo?.country ||
  input.country
);


// ------------------------------------------------------------
// 6. RAW LOCATION STRING
// ------------------------------------------------------------

let rawLocation = "";

if (typeof locationObject === "string") {

  rawLocation = locationObject;

} else {

  rawLocation = clean(
    locationObject?.full ||
    locationObject?.formatted ||
    locationObject?.address ||
    candidate.location_text ||
    candidate.locationText ||
    candidate.address_text ||
    candidate.addressText ||
    ""
  );
}


// ------------------------------------------------------------
// 7. INDIA CITY → STATE INFERENCE
// ------------------------------------------------------------
// Only infer location when actual location text contains evidence.
// DO NOT infer location from college/institution.
// ------------------------------------------------------------

const indianLocations = {

  "new delhi": ["New Delhi", "Delhi"],
  "delhi": ["Delhi", "Delhi"],

  "hyderabad": ["Hyderabad", "Telangana"],
  "secunderabad": ["Hyderabad", "Telangana"],
  "warangal": ["Warangal", "Telangana"],

  "bengaluru": ["Bengaluru", "Karnataka"],
  "bangalore": ["Bengaluru", "Karnataka"],
  "mysuru": ["Mysuru", "Karnataka"],
  "mysore": ["Mysuru", "Karnataka"],

  "chennai": ["Chennai", "Tamil Nadu"],
  "coimbatore": ["Coimbatore", "Tamil Nadu"],

  "mumbai": ["Mumbai", "Maharashtra"],
  "pune": ["Pune", "Maharashtra"],
  "nagpur": ["Nagpur", "Maharashtra"],

  "gurugram": ["Gurugram", "Haryana"],
  "gurgaon": ["Gurugram", "Haryana"],

  "noida": ["Noida", "Uttar Pradesh"],
  "lucknow": ["Lucknow", "Uttar Pradesh"],

  "jaipur": ["Jaipur", "Rajasthan"],

  "ahmedabad": ["Ahmedabad", "Gujarat"],
  "surat": ["Surat", "Gujarat"],

  "kochi": ["Kochi", "Kerala"],
  "thiruvananthapuram": [
    "Thiruvananthapuram",
    "Kerala"
  ],
  "trivandrum": [
    "Thiruvananthapuram",
    "Kerala"
  ],

  "kolkata": ["Kolkata", "West Bengal"],

  "bhubaneswar": ["Bhubaneswar", "Odisha"],

  "chandigarh": [
    "Chandigarh",
    "Chandigarh"
  ],

  "indore": ["Indore", "Madhya Pradesh"],
  "bhopal": ["Bhopal", "Madhya Pradesh"],

  "patna": ["Patna", "Bihar"],

  "visakhapatnam": [
    "Visakhapatnam",
    "Andhra Pradesh"
  ],

  "vijayawada": [
    "Vijayawada",
    "Andhra Pradesh"
  ]
};


if ((!city || !state) && rawLocation) {

  const lowerLocation = rawLocation.toLowerCase();

  // Longest names first.
  const cityKeys = Object
    .keys(indianLocations)
    .sort((a, b) => b.length - a.length);

  for (const key of cityKeys) {

    if (lowerLocation.includes(key)) {

      const resolved = indianLocations[key];

      city = city || resolved[0];
      state = state || resolved[1];

      break;
    }
  }
}


// ------------------------------------------------------------
// 8. COUNTRY INFERENCE
// ------------------------------------------------------------

if (!country) {

  const evidence = [
    rawLocation,
    city,
    state
  ]
    .join(" ")
    .toLowerCase();

  const indiaSignals = [

    "india",

    "telangana",
    "karnataka",
    "tamil nadu",
    "maharashtra",
    "delhi",
    "haryana",
    "uttar pradesh",
    "rajasthan",
    "gujarat",
    "kerala",
    "west bengal",
    "odisha",
    "madhya pradesh",
    "andhra pradesh",
    "bihar",

    "hyderabad",
    "bangalore",
    "bengaluru",
    "chennai",
    "mumbai",
    "pune",
    "gurgaon",
    "gurugram",
    "noida",
    "kolkata",
    "kochi"
  ];

  if (
    indiaSignals.some(signal =>
      evidence.includes(signal)
    )
  ) {
    country = "India";
  }
}


// Current product is India-first.
// If resume contains no country information,
// India becomes the search-country fallback.
country = country || "India";


// ------------------------------------------------------------
// 9. GEOGRAPHIC POLICY
// ------------------------------------------------------------

const preciseLocationAvailable =
  Boolean(city || state);

const geographyPolicy = {

  same_state_minimum:
    state ? 4 : 0,

  same_country_minimum: 7,

  international_maximum: 3,

  international_remote_preferred: true,

  precise_location_available:
    preciseLocationAvailable,

  candidate_city:
    city || null,

  candidate_state:
    state || null,

  candidate_country:
    country
};


// ------------------------------------------------------------
// 10. SEARCH QUERY CONTAINER
// ------------------------------------------------------------

const searches = [];

function addSearch({
  query,
  discovery_type,
  priority,
  geography,
  source_family
}) {

  if (!query) return;

  searches.push({
    query,
    discovery_type,
    priority,
    geography,
    source_family
  });
}


// ------------------------------------------------------------
// 11. OFFICIAL ATS SOURCES
// ------------------------------------------------------------
// These receive highest priority because they frequently point
// directly to employer-controlled job listings.
// ------------------------------------------------------------

const officialATS = [

  {
    domain: "jobs.lever.co",
    name: "Lever"
  },

  {
    domain: "boards.greenhouse.io",
    name: "Greenhouse"
  },

  {
    domain: "job-boards.greenhouse.io",
    name: "Greenhouse"
  },

  {
    domain: "jobs.ashbyhq.com",
    name: "Ashby"
  },

  {
    domain: "apply.workable.com",
    name: "Workable"
  },

  {
    domain: "careers.smartrecruiters.com",
    name: "SmartRecruiters"
  }
];


// ------------------------------------------------------------
// 12. OFFICIAL ATS — COUNTRY SEARCHES
// ------------------------------------------------------------

for (const role of targetRoles) {

  for (const ats of officialATS) {

    addSearch({

      query:
        `site:${ats.domain} "${role}" "${country}"`,

      discovery_type:
        "official_ats",

      priority: 1,

      geography:
        "country",

      source_family:
        ats.name
    });
  }
}


// ------------------------------------------------------------
// 13. OFFICIAL ATS — STATE SEARCHES
// ------------------------------------------------------------

if (state) {

  for (const role of targetRoles) {

    for (const ats of officialATS.slice(0, 4)) {

      addSearch({

        query:
          `site:${ats.domain} "${role}" "${state}"`,

        discovery_type:
          "official_ats_state",

        priority: 1,

        geography:
          "state",

        source_family:
          ats.name
      });
    }
  }
}


// ------------------------------------------------------------
// 14. CITY-LEVEL OFFICIAL SEARCH
// ------------------------------------------------------------

if (city) {

  for (const role of targetRoles) {

    addSearch({

      query:
        `"${role}" "${city}" careers ${stageTerm}`,

      discovery_type:
        "official_city",

      priority: 1,

      geography:
        "city",

      source_family:
        "official_web"
    });
  }
}


// ------------------------------------------------------------
// 15. STATE-LEVEL COMPANY CAREER SEARCH
// ------------------------------------------------------------

if (state) {

  for (const role of targetRoles) {

    addSearch({

      query:
        `"${role}" "${state}" company careers`,

      discovery_type:
        "official_state",

      priority: 1,

      geography:
        "state",

      source_family:
        "official_web"
    });
  }
}


// ------------------------------------------------------------
// 16. INDIA / COUNTRY COMPANY CAREERS
// ------------------------------------------------------------

for (const role of targetRoles) {

  addSearch({

    query:
      `"${role}" "${country}" company careers`,

    discovery_type:
      "official_country",

    priority: 1,

    geography:
      "country",

    source_family:
      "official_web"
  });


  addSearch({

    query:
      `"${role}" "${country}" startup careers`,

    discovery_type:
      "startup_careers",

    priority: 1,

    geography:
      "country",

    source_family:
      "startup_official"
  });
}


// ------------------------------------------------------------
// 17. STARTUP / TECH COMPANY DISCOVERY
// ------------------------------------------------------------

for (const role of targetRoles.slice(0, 3)) {

  const geo = city || state || country;

  addSearch({

    query:
      `"${role}" "${geo}" startup ${stageTerm} hiring`,

    discovery_type:
      "startup_discovery",

    priority: 2,

    geography:
      city ? "city" :
      state ? "state" :
      "country",

    source_family:
      "startup_web"
  });
}


// ------------------------------------------------------------
// 18. SKILL-BASED DISCOVERY
// ------------------------------------------------------------
// Helps find relevant opportunities whose titles don't exactly
// match our generated target roles.
// ------------------------------------------------------------

const importantSkills =
  allTechnicalSkills.slice(0, 5);

for (const skill of importantSkills) {

  addSearch({

    query:
      `"${skill}" ${stageTerm} "${country}" careers`,

    discovery_type:
      "skill_discovery",

    priority: 2,

    geography:
      "country",

    source_family:
      "skill_web"
  });
}


// ------------------------------------------------------------
// 19. THIRD-PARTY DISCOVERY
// ------------------------------------------------------------
// Lower priority than official sources.
// These help increase coverage.
// ------------------------------------------------------------

for (const role of targetRoles.slice(0, 3)) {

  addSearch({

    query:
      `site:linkedin.com/jobs "${role}" "${country}"`,

    discovery_type:
      "linkedin",

    priority: 3,

    geography:
      "country",

    source_family:
      "LinkedIn"
  });


  // Internshala is internship-oriented; skip it for candidates targeting jobs.
  if (wantsInternship) addSearch({

    query:
      `site:internshala.com "${role}" "${country}"`,

    discovery_type:
      "internshala",

    priority: 3,

    geography:
      "country",

    source_family:
      "Internshala"
  });
}


// ------------------------------------------------------------
// 20. INTERNATIONAL REMOTE
// ------------------------------------------------------------
// International results are intentionally remote-oriented.
// ------------------------------------------------------------

for (const role of targetRoles.slice(0, 2)) {

  addSearch({

    query:
      `"${role}" remote worldwide careers`,

    discovery_type:
      "international_remote",

    priority: 4,

    geography:
      "international_remote",

    source_family:
      "international_web"
  });


  addSearch({

    query:
      `site:jobs.lever.co "${role}" remote`,

    discovery_type:
      "international_official_remote",

    priority: 4,

    geography:
      "international_remote",

    source_family:
      "Lever"
  });


  addSearch({

    query:
      `site:boards.greenhouse.io "${role}" remote`,

    discovery_type:
      "international_official_remote",

    priority: 4,

    geography:
      "international_remote",

    source_family:
      "Greenhouse"
  });
}


// ------------------------------------------------------------
// 21. QUERY DEDUPLICATION
// ------------------------------------------------------------

const seenQueries = new Set();

const uniqueSearches = searches.filter(item => {

  const normalized =
    item.query
      .toLowerCase()
      .replace(/\s+/g, " ")
      .trim();

  if (seenQueries.has(normalized)) {
    return false;
  }

  seenQueries.add(normalized);

  return true;
});


// ------------------------------------------------------------
// 22. PRIORITY SORTING
// ------------------------------------------------------------

uniqueSearches.sort((a, b) => {

  if (a.priority !== b.priority) {
    return a.priority - b.priority;
  }

  const geographyRank = {
    city: 1,
    state: 2,
    country: 3,
    international_remote: 4
  };

  return (
    (geographyRank[a.geography] || 99) -
    (geographyRank[b.geography] || 99)
  );
});


