    resultIndex++
  ) {
    const result = results[resultIndex] ?? {};

    const originalUrl = cleanText(result.url);

    if (!originalUrl) {
      continue;
    }

    const canonicalUrl = canonicalizeUrl(originalUrl);
    const domain = getDomain(originalUrl);

    output.push({
      json: {
