// =====================================================================
// GENERIC HELPERS
// =====================================================================

function safeString(value) {
  if (value === undefined || value === null) return '';
  return String(value);
}

function toArrayField(value) {
  if (Array.isArray(value)) {
    return value.map((v) => safeString(v).trim()).filter(Boolean);
  }
  const str = safeString(value).trim();
  if (!str) return [];
  return str.split(/[,;|]/).map((v) => v.trim()).filter(Boolean);
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

// =====================================================================
// 1. URL NORMALIZATION
// =====================================================================

function normalizeUrl(rawUrl) {
  const original = safeString(rawUrl).trim();
  if (!original) return { normalized: '', hostname: '', valid: false };

  let workingUrl = original;
  if (!/^https?:\/\//i.test(workingUrl)) {
    workingUrl = 'https://' + workingUrl.replace(/^\/\//, '');
  }

  let parsed;
  try {
    parsed = new URL(workingUrl);
  } catch (err) {
    return { normalized: original.toLowerCase(), hostname: '', valid: false };
  }

  let hostname = parsed.hostname.toLowerCase();
  if (hostname.startsWith('www.')) hostname = hostname.slice(4);

  const params = new URLSearchParams(parsed.search);
  CONFIG.TRACKING_PARAMS.forEach((p) => params.delete(p));

  const remainingParams = [];
  for (const [key, value] of params.entries()) {
    remainingParams.push([key, value]);
  }
  remainingParams.sort((a, b) => a[0].localeCompare(b[0]));
  const queryString = remainingParams
    .map(([k, v]) => `${k}=${v}`)
    .join('&');

  let pathname = parsed.pathname.replace(/\/{2,}/g, '/');
  if (pathname.length > 1 && pathname.endsWith('/')) {
    pathname = pathname.slice(0, -1);
  }
  if (!pathname) pathname = '/';

  const normalized = `https://${hostname}${pathname}${queryString ? '?' + queryString : ''}`;

  return { normalized, hostname, valid: true };
}

// =====================================================================
// TITLE NORMALIZATION AND SIMILARITY
// =====================================================================

const TITLE_SUFFIX_PATTERNS = [
  /\s*[\|\-–—]\s*linkedin.*$/i,
  /\s*[\|\-–—]\s*indeed(\.com)?.*$/i,
  /\s*[\|\-–—]\s*glassdoor.*$/i,
  /\s*[\|\-–—]\s*ziprecruiter.*$/i,
  /\s*[\|\-–—]\s*careers?(\s+at)?.*$/i
];

function normalizeTitle(rawTitle) {
  let title = safeString(rawTitle).toLowerCase().trim();
  title = title.replace(/\s*[\(\[]\s*(duplicate from board|sponsored|ad|reposted)\s*[\)\]]/ig, ' ');
  TITLE_SUFFIX_PATTERNS.forEach((pattern) => {
    title = title.replace(pattern, '');
  });
  title = title.replace(/[^a-z0-9\s]/g, ' ');
  title = title.replace(/\s+/g, ' ').trim();
  return title;
}

function diceCoefficient(a, b) {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;

  const bigrams = (s) => {
    const map = new Map();
    for (let i = 0; i < s.length - 1; i++) {
      const bg = s.substring(i, i + 2);
      map.set(bg, (map.get(bg) || 0) + 1);
    }
    return map;
  };

  const aBigrams = bigrams(a);
  const bBigrams = bigrams(b);
  let intersection = 0;
  for (const [bg, count] of aBigrams) {
    if (bBigrams.has(bg)) {
      intersection += Math.min(count, bBigrams.get(bg));
    }
  }
  const totalBigrams = (a.length - 1) + (b.length - 1);
  return totalBigrams === 0 ? 0 : (2 * intersection) / totalBigrams;
}

function extractCompanyRoleSignature(title) {
  const raw = safeString(title).trim();
  let match = raw.match(/^(.*?)\s+at\s+(.*)$/i);
  if (match) {
    const role = normalizeTitle(match[1]);
    const company = normalizeTitle(match[2]);
    return { role, company, signature: [company, role].sort().join('|') };
  }
  match = raw.match(/^(.*?)\s*[-–|]\s*(.*)$/);
  if (match) {
    const left = normalizeTitle(match[1]);
    const right = normalizeTitle(match[2]);
    return { role: right, company: left, signature: [left, right].sort().join('|') };
  }
  const normalized = normalizeTitle(raw);
  return { role: normalized, company: '', signature: normalized };
}

// =====================================================================
// 3. SOURCE QUALITY
// =====================================================================

function classifySourceQuality(hostname, sourceFamily) {
  const family = safeString(sourceFamily).toLowerCase();

  if (ATS_DOMAIN_PATTERNS.some((p) => p.test(hostname))) {
    return { tier: 'highest', score: CONFIG.SOURCE_TIER_SCORES.highest, basis: 'known official ATS domain' };
  }
  if (/official.?ats|official.?career/.test(family)) {
    return { tier: 'highest', score: CONFIG.SOURCE_TIER_SCORES.highest, basis: 'source_family: official ATS/careers' };
  }
  if (GOV_EDU_RESEARCH_PATTERNS.some((p) => p.test(hostname))) {
    return { tier: 'high', score: CONFIG.SOURCE_TIER_SCORES.high, basis: 'government/university/research domain' };
  }
  if (/government|university|research.?lab|\bedu\b|\bgov\b/.test(family)) {
    return { tier: 'high', score: CONFIG.SOURCE_TIER_SCORES.high, basis: 'source_family: government/university/research' };
  }
  if (PLATFORM_DOMAIN_PATTERNS.some((p) => p.test(hostname))) {
    return { tier: 'medium', score: CONFIG.SOURCE_TIER_SCORES.medium, basis: 'known internship/job platform domain' };
  }
  if (/internship.?platform|job.?board|platform/.test(family)) {
    return { tier: 'medium', score: CONFIG.SOURCE_TIER_SCORES.medium, basis: 'source_family: internship/job platform' };
  }
  if (AGGREGATOR_DOMAIN_PATTERNS.some((p) => p.test(hostname))) {
    return { tier: 'lower', score: CONFIG.SOURCE_TIER_SCORES.lower, basis: 'known aggregator domain' };
  }
  if (/aggregator/.test(family)) {
    return { tier: 'lower', score: CONFIG.SOURCE_TIER_SCORES.lower, basis: 'source_family: aggregator' };
  }
  if (/spam/.test(family)) {
    return { tier: 'lowest', score: CONFIG.SOURCE_TIER_SCORES.lowest, basis: 'source_family: spam' };
  }

  return { tier: 'unknown', score: CONFIG.SOURCE_TIER_SCORES.unknown, basis: 'unrecognized source; defaulted to unknown tier' };
}

// =====================================================================
// 4. OPPORTUNITY DETECTION
// =====================================================================

function detectOpportunityType(title, content, url, discoveryType) {
  const text = `${safeString(title)} ${safeString(content)}`;
  const path = safeString(url);

  let negativeScore = 0;
  const rejectReasons = [];
  Object.entries(REJECT_PAGE_TYPE_PATTERNS).forEach(([label, def]) => {
    const hit = def.patterns.some((p) => p.test(text));
    if (hit) {
      negativeScore += def.weight;
      rejectReasons.push(`matched non-opportunity signal: ${label}`);
    }
  });
  NEGATIVE_PATH_PATTERNS.forEach((p) => {
    if (p.test(path)) {
      negativeScore += 2;
      rejectReasons.push('URL path suggests non-opportunity content');
    }
  });
  // A listing/search URL is disqualifying on its own: there is no single
  // posting behind it to apply to (product rule 5). Weighted the same as the
  // title-based aggregator signal so it cannot be outvoted by a strong domain.
  if (LISTING_URL_PATTERNS.some((p) => p.test(path))) {
    negativeScore += 10;
    rejectReasons.push('URL is a search/listing page, not a specific posting');
  }
  // A social/video host is disqualifying outright — there is no posting behind
  // it under any circumstances, so it gets a weight nothing can outvote rather
  // than the 10 a listing page earns.
  try {
    if (path && isNonJobHost(new URL(/^https?:\/\//i.test(path) ? path : 'https://' + path).hostname)) {
      negativeScore += 100;
      rejectReasons.push('Host does not serve job postings');
    }
  } catch (err) {
    // Unparseable URL: leave scoring to the other signals rather than guessing.
  }

  let positiveScore = 0;
  const acceptSignals = [];
  let bestType = null;
  let bestTypeScore = 0;
  Object.entries(ACCEPT_PAGE_TYPE_PATTERNS).forEach(([label, def]) => {
    const hits = def.patterns.filter((p) => p.test(text)).length;
    if (hits > 0) {
      const contribution = def.weight * hits;
      positiveScore += contribution;
      acceptSignals.push(`matched opportunity signal: ${label}`);
      if (contribution > bestTypeScore) {
        bestTypeScore = contribution;
        bestType = label;
      }
    }
  });
  POSITIVE_PATH_PATTERNS.forEach((p) => {
    if (p.test(path)) {
      positiveScore += 2;
      acceptSignals.push('URL path suggests opportunity content');
    }
  });

  const knownDiscoveryTypes = Object.keys(ACCEPT_PAGE_TYPE_PATTERNS).map((t) => t.toLowerCase());
  const discoveryTypeNormalized = safeString(discoveryType).toLowerCase();
  if (discoveryTypeNormalized && knownDiscoveryTypes.includes(discoveryTypeNormalized)) {
    positiveScore += 2;
    acceptSignals.push('upstream discovery_type aligns with recognized opportunity category');
    if (!bestType) {
      bestType = Object.keys(ACCEPT_PAGE_TYPE_PATTERNS).find(
        (t) => t.toLowerCase() === discoveryTypeNormalized
      );
    }
  }

  const isOpportunity =
    positiveScore >= CONFIG.REJECTION.MIN_OPPORTUNITY_POSITIVE_SCORE &&
    positiveScore > negativeScore;

  return {
    isOpportunity,
    positiveScore,
    negativeScore,
    inferredType: isOpportunity ? (bestType || safeString(discoveryType) || 'Opportunity') : null,
    acceptSignals,
    rejectReasons
  };
}

// =====================================================================
// 5. CANDIDATE RELEVANCE
// =====================================================================

function computeCandidateRelevance(item) {
  const roles = toArrayField(item.target_roles);
  const skills = toArrayField(item.candidate_skills);
  const text = `${safeString(item.title)} ${safeString(item.content)}`.toLowerCase();

  if (roles.length === 0 && skills.length === 0) {
    return {
      score: 50,
      hasProfileSignal: false,
      matchedRoles: [],
      matchedSkills: [],
      note: 'no candidate role/skill profile data available on this item; neutral score applied'
    };
  }

  const matchedRoles = roles.filter((r) => text.includes(r.toLowerCase()));
  const matchedSkills = skills.filter((s) => text.includes(s.toLowerCase()));

  const roleRatio = roles.length > 0 ? matchedRoles.length / roles.length : 0;
  const skillRatio = skills.length > 0 ? matchedSkills.length / skills.length : 0;

  let score = roleRatio * 65 + skillRatio * 35;

  const titleLower = safeString(item.title).toLowerCase();
  if (roles.some((r) => titleLower.includes(r.toLowerCase()))) {
    score += 10;
  }

  score = clamp(score, 0, 100);

  return {
    score,
    hasProfileSignal: true,
    matchedRoles,
    matchedSkills,
    note: `${matchedRoles.length}/${roles.length || 0} target roles and ${matchedSkills.length}/${skills.length || 0} skills matched in page text`
  };
}

// =====================================================================
// 6. GEOGRAPHY QUALITY
// =====================================================================

function computeGeographyRelevance(item) {
  const text = `${safeString(item.title)} ${safeString(item.content)} ${safeString(item.search_geography)}`.toLowerCase();
  const city = safeString(item.candidate_city).toLowerCase().trim();
  const state = safeString(item.candidate_state).toLowerCase().trim();
  const country = safeString(item.candidate_country).toLowerCase().trim();
  const policy = safeString(item.geography_policy).toLowerCase();
  const isStrictPolicy = /local|city|state/.test(policy);
  const allowsInternational = /international|global|any|worldwide/.test(policy) || policy === '';
  const isRemoteMention = /\bremote\b|\bwork from home\b|\bwfh\b/.test(text);

  let tier = 'unknown';
  let score = 50;
  let note = 'no location signal detected in page text; geography unverified';

  if (city && text.includes(city)) {
    tier = 'city';
    score = 100;
    note = `matched candidate city (${item.candidate_city})`;
  } else if (state && text.includes(state)) {
    tier = 'state';
    score = 85;
    note = `matched candidate state/region (${item.candidate_state})`;
  } else if (country && text.includes(country)) {
    tier = 'country';
    score = 70;
    note = `matched candidate country (${item.candidate_country})`;
  } else if (isRemoteMention) {
    tier = 'remote';
    score = 75;
    note = 'opportunity indicates remote eligibility';
  } else if (allowsInternational) {
    tier = 'international';
    score = 60;
    note = 'no direct location match, but geography policy permits international opportunities';
  } else {
    tier = 'mismatch';
    score = 15;
    note = 'no match found between candidate location and opportunity location; policy is restrictive';
  }

  const hardMismatch = isStrictPolicy && !['city', 'state', 'remote'].includes(tier);

  return { score, tier, note, hardMismatch };
}

// =====================================================================
// 7. FRESHNESS
// =====================================================================

function computeFreshness(item) {
  const text = `${safeString(item.title)} ${safeString(item.content)}`;
  const now = new Date();
  const currentYear = now.getFullYear();

  let recencyScore = 50;
  let discoveredAtNote = 'discovered_at missing or unparseable; neutral recency applied';
  const discoveredAt = new Date(safeString(item.discovered_at));
  if (!isNaN(discoveredAt.getTime())) {
    const ageDays = (now.getTime() - discoveredAt.getTime()) / 86400000;
    if (ageDays <= 3) recencyScore = 100;
    else if (ageDays <= 7) recencyScore = 90;
    else if (ageDays <= 14) recencyScore = 80;
    else if (ageDays <= 30) recencyScore = 65;
    else if (ageDays <= 60) recencyScore = 45;
    else if (ageDays <= 90) recencyScore = 25;
    else recencyScore = 10;
    discoveredAtNote = `discovered ${Math.max(0, Math.round(ageDays))} day(s) ago`;
  }

  let contentAdjustment = 0;
  const notes = [];

  const yearPattern = new RegExp(`\\b(${currentYear}|${currentYear + 1})\\b`);
  if (yearPattern.test(text)) {
    contentAdjustment += 8;
    notes.push('current/upcoming year referenced in page content');
  }

  const staleYearPattern = /\b(201[0-9]|202[0-3])\b/;
  if (staleYearPattern.test(text) && !yearPattern.test(text)) {
    contentAdjustment -= 15;
    notes.push('only older year references found in page content');
  }

  if (OPEN_SIGNAL_PATTERNS.some((p) => p.test(text))) {
    contentAdjustment += 10;
    notes.push('open-application signals present');
  }

  let closedSignal = false;
  if (CLOSED_SIGNAL_PATTERNS.some((p) => p.test(text))) {
    contentAdjustment -= 40;
    closedSignal = true;
    notes.push('page explicitly indicates the opportunity is closed/filled/expired');
  }

  const score = clamp(recencyScore + contentAdjustment, 0, 100);

  return {
    score,
    closedSignal,
    note: [discoveredAtNote, ...notes].join('; ')
  };
}

// =====================================================================
// TITLE / CONTENT QUALITY
// =====================================================================

const ROLE_HINT_WORDS = /\b(intern|internship|fellow|fellowship|scholar|scholarship|hackathon|competition|program|position|associate|engineer|analyst|researcher|developer|assistant)\b/i;
const CLICKBAIT_WORDS = /\b(you won'?t believe|shocking|top \d+ secrets|number \d+ will)\b/i;

function computeTitleQuality(title) {
  const t = safeString(title).trim();
  let score = 50;
  const notes = [];

  if (t.length < 10) {
    score -= 20;
    notes.push('title unusually short');
  } else if (t.length > 150) {
    score -= 10;
    notes.push('title unusually long');
  } else {
    score += 10;
  }

  if (ROLE_HINT_WORDS.test(t)) {
    score += 25;
    notes.push('title contains a clear opportunity-type keyword');
  }

  if (CLICKBAIT_WORDS.test(t)) {
    score -= 30;
    notes.push('title contains clickbait phrasing');
  }

  if (t === t.toUpperCase() && t.length > 15) {
    score -= 15;
    notes.push('title is all caps, possible low-quality listing');
  }

  return { score: clamp(score, 0, 100), note: notes.join('; ') || 'no notable title quality signals' };
}

const STRUCTURED_CONTENT_HINTS = /\b(responsibilit(y|ies)|qualifications|eligibility|deadline|requirements|stipend|compensation|duration|how to apply)\b/i;

function computeContentQuality(content) {
  const c = safeString(content).trim();
  let score = 50;
  const notes = [];

  if (c.length < 40) {
    score -= 30;
    notes.push('content extremely thin');
  } else if (c.length < 150) {
    score -= 10;
    notes.push('content below optimal length');
  } else {
    score += 10;
  }

  if (STRUCTURED_CONTENT_HINTS.test(c)) {
    score += 25;
    notes.push('content contains structured application details');
  }

  if (SPAM_TEXT_SIGNALS.some((p) => p.test(c))) {
    score -= 50;
    notes.push('content contains spam-like phrasing');
  }

  return { score: clamp(score, 0, 100), note: notes.join('; ') || 'no notable content quality signals' };
}

// =====================================================================
// SEARCH SCORE NORMALIZATION
// =====================================================================

function normalizeSearchScore(rawScore) {
  const n = Number(rawScore);
  if (isNaN(n)) return 50;
  if (n <= 1) return clamp(n * 100, 0, 100);
  return clamp(n, 0, 100);
}

function normalizeSearchPriority(rawPriority) {
  if (rawPriority === undefined || rawPriority === null || rawPriority === '') return null;
  const n = Number(rawPriority);
  if (!isNaN(n)) {
    return n <= 1 ? clamp(n * 100, 0, 100) : clamp(n, 0, 100);
  }
  const p = safeString(rawPriority).toLowerCase();
  if (/critical|urgent/.test(p)) return 100;
  if (/high/.test(p)) return 90;
  if (/medium|normal/.test(p)) return 60;
  if (/low/.test(p)) return 30;
  return 50;
}

// =====================================================================
// DEDUPLICATION (union-find over multiple strategies)
// =====================================================================

class DisjointSet {
  constructor(n) {
    this.parent = Array.from({ length: n }, (_, i) => i);
  }
  find(x) {
    while (this.parent[x] !== x) {
      this.parent[x] = this.parent[this.parent[x]];
      x = this.parent[x];
    }
    return x;
  }
  union(a, b) {
    const ra = this.find(a);
    const rb = this.find(b);
    if (ra !== rb) this.parent[ra] = rb;
  }
}

function buildDedupClusters(records) {
  const n = records.length;
  const ds = new DisjointSet(n);

  // Strategy 1: exact normalized URL
  const byUrl = new Map();
  records.forEach((r, i) => {
    if (!r.normalizedUrl) return;
    if (byUrl.has(r.normalizedUrl)) {
      ds.union(i, byUrl.get(r.normalizedUrl));
    } else {
      byUrl.set(r.normalizedUrl, i);
    }
  });

  // Strategy 2: canonical URL (may differ from normalized raw URL if source supplied its own canonical)
  const byCanonical = new Map();
  records.forEach((r, i) => {
    if (!r.canonicalUrl) return;
    if (byCanonical.has(r.canonicalUrl)) {
      ds.union(i, byCanonical.get(r.canonicalUrl));
    } else {
      byCanonical.set(r.canonicalUrl, i);
    }
  });

  // Strategy 3: case-insensitive normalized URL.
  //
  // normalizeUrl lowercases the HOST but deliberately leaves the PATH alone,
  // because paths are case-sensitive on some servers and folding them into the
  // canonical form could merge two genuinely different pages. But job-board
  // ids are not case-sensitive in practice, and a real run discovered the same
  // Workable posting twice:
  //     apply.workable.com/minderacraft/j/49D461FD97
  //     apply.workable.com/minderacraft/j/49d461fd97
  // Two records, two renders, two scoring calls, one job. Unioning on a
  // lowercased key here merges those without changing normalizedUrl itself,
  // so nothing downstream that relies on the exact URL is affected.
  const byLowerUrl = new Map();
  records.forEach((r, i) => {
    if (!r.normalizedUrl) return;
    const key = String(r.normalizedUrl).toLowerCase();
    if (byLowerUrl.has(key)) {
      ds.union(i, byLowerUrl.get(key));
    } else {
      byLowerUrl.set(key, i);
    }
  });

  // Strategy 4: fuzzy title similarity within the same hostname bucket
  const byHost = new Map();
  records.forEach((r, i) => {
    if (!r.hostname) return;
    if (!byHost.has(r.hostname)) byHost.set(r.hostname, []);
    byHost.get(r.hostname).push(i);
  });
  byHost.forEach((indices) => {
    for (let a = 0; a < indices.length; a++) {
      for (let b = a + 1; b < indices.length; b++) {
        const i = indices[a];
        const j = indices[b];
        if (
          records[i].normalizedTitle.length < CONFIG.DEDUP.MIN_TITLE_LENGTH_FOR_FUZZY_MATCH ||
          records[j].normalizedTitle.length < CONFIG.DEDUP.MIN_TITLE_LENGTH_FOR_FUZZY_MATCH
        ) {
          continue;
        }
        const sim = diceCoefficient(records[i].normalizedTitle, records[j].normalizedTitle);
        if (sim >= CONFIG.DEDUP.TITLE_SIMILARITY_THRESHOLD) {
          ds.union(i, j);
        }
      }
    }
  });

  // Strategy 5: company + role signature similarity (repeated opportunity surfaced via different wording)
  const bySignatureBucket = new Map();
  records.forEach((r, i) => {
    if (!r.companyRoleSignature.company) return;
    const key = r.companyRoleSignature.company;
    if (!key) return;
    if (!bySignatureBucket.has(key)) bySignatureBucket.set(key, []);
    bySignatureBucket.get(key).push(i);
  });
  bySignatureBucket.forEach((indices) => {
    for (let a = 0; a < indices.length; a++) {
      for (let b = a + 1; b < indices.length; b++) {
        const i = indices[a];
        const j = indices[b];
        const sim = diceCoefficient(
          records[i].companyRoleSignature.signature,
          records[j].companyRoleSignature.signature
        );
        if (sim >= CONFIG.DEDUP.COMPANY_ROLE_SIMILARITY_THRESHOLD) {
          ds.union(i, j);
        }
      }
    }
  });

  const clusters = new Map();
  for (let i = 0; i < n; i++) {
    const root = ds.find(i);
    if (!clusters.has(root)) clusters.set(root, []);
    clusters.get(root).push(i);
  }
  return Array.from(clusters.values());
}

function chooseStrongestInCluster(records, indices) {
  const sorted = [...indices].sort((a, b) => {
    const ra = records[a];
    const rb = records[b];

    if (rb.sourceQuality.score !== ra.sourceQuality.score) {
      return rb.sourceQuality.score - ra.sourceQuality.score;
    }
    const scoreA = normalizeSearchScore(ra.raw.score);
    const scoreB = normalizeSearchScore(rb.raw.score);
    if (scoreB !== scoreA) return scoreB - scoreA;

    const contentLenA = safeString(ra.raw.content).length;
    const contentLenB = safeString(rb.raw.content).length;
    if (contentLenB !== contentLenA) return contentLenB - contentLenA;

    const dateA = new Date(safeString(ra.raw.discovered_at)).getTime() || 0;
    const dateB = new Date(safeString(rb.raw.discovered_at)).getTime() || 0;
    if (dateB !== dateA) return dateB - dateA;

    return safeString(ra.raw.query_id).localeCompare(safeString(rb.raw.query_id));
  });
  return sorted[0];
}

// =====================================================================
// MAIN PIPELINE
// =====================================================================

const inputItems = $input.all();
const rawList = inputItems.map((i) => i.json || {});

// ---- Pre-processing pass: normalize URL/title, classify source quality ----
const records = rawList.map((raw) => {
  const urlInfo = normalizeUrl(raw.url || raw.canonical_url);
  const canonicalInfo = normalizeUrl(raw.canonical_url || raw.url);
  const normalizedTitle = normalizeTitle(raw.title);
  const companyRoleSignature = extractCompanyRoleSignature(raw.title);
  const sourceQuality = classifySourceQuality(urlInfo.hostname || canonicalInfo.hostname, raw.source_family);

  return {
    raw,
    normalizedUrl: urlInfo.normalized,
    canonicalUrl: canonicalInfo.normalized,
    hostname: urlInfo.hostname || canonicalInfo.hostname,
    normalizedTitle,
    companyRoleSignature,
    sourceQuality
  };
})
// Hard-drop social/video/forum hosts (instagram.com/reel/... etc.): never
// job postings. A score penalty alone let them survive the broadened pass,
// so exclude them here before dedup, admission, and relaxation ever see them.
.filter((r) => !isNonJobHost(r.hostname));

// ---- Deduplication ----
const clusters = buildDedupClusters(records);

// ---- Admission, in up to two passes -------------------------------------
// The product rule is: if the first pass yields too few qualifying items,
// broaden BEFORE falling back to the weak-resume path. Broadening here relaxes
// candidate-relevance and opportunity-signal margins over the postings we have
// ALREADY discovered, rather than issuing more searches.
//
// Why not a cyclic n8n graph (re-search -> re-scrape -> re-score): the If node's
// two branches reconverge into Loop Over Items, which is exactly what forced
// batchSize to 1 — a second feedback path into splitInBatches makes its
// done-branch fire repeatedly and emit partial results. A cycle would re-enter
// that same already-completed loop. Measured, not assumed.
//
// Tradeoff, stated plainly: this cannot surface a posting that discovery never
// found. It only stops us discarding ones we did find. A genuinely thin profile
// with few real matches still returns few results — which is correct.
const BROADEN_IF_FEWER_THAN = 12;   // below this, ~5 survivors post-scoring is unlikely
const RELAXED_RELEVANCE_FLOOR = 6;  // half the strict floor of 12
const MAX_ADMITTED = 30;            // cap scraping cost

function admitClusters(relaxed) {
  const survivors = [];

clusters.forEach((clusterIndices) => {
  try {
    const winnerIndex = chooseStrongestInCluster(records, clusterIndices);
    const winner = records[winnerIndex];
    const raw = winner.raw;

    // Aggregate multi-query evidence across the whole cluster.
    const evidenceMap = new Map();
    clusterIndices.forEach((idx) => {
      const r = records[idx].raw;
      const key = `${safeString(r.query_id)}::${safeString(r.search_query)}`;
      if (!evidenceMap.has(key)) {
        evidenceMap.set(key, {
          query_id: safeString(r.query_id),
          search_query: safeString(r.search_query),
          discovery_engine: safeString(r.discovery_engine)
        });
      }
    });
    const multiQueryEvidence = Array.from(evidenceMap.values());
    const distinctQueryCount = new Set(multiQueryEvidence.map((e) => e.query_id || e.search_query)).size;

    // ---- Opportunity detection ----
    const opportunityDetection = detectOpportunityType(
      raw.title,
      raw.content,
      winner.canonicalUrl || raw.url,
      raw.discovery_type
    );
    if (!opportunityDetection.isOpportunity) {
      return; // hard reject: not a genuine opportunity page
    }

    // ---- Candidate relevance ----
    const candidateRelevance = computeCandidateRelevance(raw);
    const relevanceFloor = relaxed
      ? RELAXED_RELEVANCE_FLOOR
      : CONFIG.REJECTION.MIN_CANDIDATE_RELEVANCE_WHEN_PROFILE_PRESENT;
    if (candidateRelevance.hasProfileSignal && candidateRelevance.score < relevanceFloor) {
      return; // hard reject: essentially unrelated to candidate profile
    }

    // ---- Geography ----
    const geography = computeGeographyRelevance(raw);
    if (geography.hardMismatch) {
      return; // hard reject: strict geography policy violated
    }

    // ---- Freshness ----
    const freshness = computeFreshness(raw);
    if (freshness.closedSignal) {
      return; // hard reject: opportunity explicitly closed/expired/filled
    }

    // ---- Title / content quality ----
    const titleQuality = computeTitleQuality(raw.title);
    const contentQuality = computeContentQuality(raw.content);

    // ---- Search score / priority ----
    const normalizedScore = normalizeSearchScore(raw.score);
    const normalizedPriority = normalizeSearchPriority(raw.search_priority);
    const searchScoreComponent =
      normalizedPriority === null ? normalizedScore : (normalizedScore + normalizedPriority) / 2;

    // ---- Multi-query evidence score ----
    const multiQueryScore =
      distinctQueryCount <= 1 ? 40 : clamp(40 + (distinctQueryCount - 1) * 20, 0, 100);

    // ---- Source tier hard gate ----
    const components = {
      sourceQuality: winner.sourceQuality.score,
      candidateRelevance: candidateRelevance.score,
      geographyRelevance: geography.score,
      freshness: freshness.score,
      searchScore: searchScoreComponent,
      multiQueryEvidence: multiQueryScore,
      titleQuality: titleQuality.score,
      contentQuality: contentQuality.score
    };

    let confidenceScore = 0;
    const breakdown = {};
    Object.entries(CONFIG.WEIGHTS).forEach(([key, weight]) => {
      const value = components[key];
      const contribution = value * weight;
      confidenceScore += contribution;
      breakdown[key] = {
        value: round2(value),
        weight,
        contribution: round2(contribution)
      };
    });
    confidenceScore = clamp(Math.round(confidenceScore), 0, 100);

    if (
      winner.sourceQuality.tier === 'lowest' &&
      confidenceScore < CONFIG.REJECTION.MIN_CONFIDENCE_FOR_LOWEST_SOURCE_TIER
    ) {
      return; // hard reject: spam-tier source with weak overall signal
    }
    if (SPAM_TEXT_SIGNALS.some((p) => p.test(safeString(raw.content)) || p.test(safeString(raw.title)))) {
      return; // hard reject: explicit spam text signals present
    }

    // ---- Explainability ----
    const acceptanceReasons = [];
    if (winner.sourceQuality.tier === 'highest' || winner.sourceQuality.tier === 'high') {
      acceptanceReasons.push(`Strong source: ${winner.sourceQuality.basis}`);
    }
    if (candidateRelevance.hasProfileSignal && candidateRelevance.score >= 50) {
      acceptanceReasons.push(`Good candidate fit: ${candidateRelevance.note}`);
    }
    if (['city', 'state', 'remote'].includes(geography.tier)) {
      acceptanceReasons.push(`Geography match: ${geography.note}`);
    }
    if (freshness.score >= 65) {
      acceptanceReasons.push(`Fresh listing: ${freshness.note}`);
    }
    if (distinctQueryCount > 1) {
      acceptanceReasons.push(`Confirmed by ${distinctQueryCount} independent searches`);
    }
    if (opportunityDetection.acceptSignals.length > 0) {
      acceptanceReasons.push(...opportunityDetection.acceptSignals.slice(0, 3));
    }
    if (acceptanceReasons.length === 0) {
      acceptanceReasons.push('Passed all quality gates with baseline signal strength');
    }

    const rejectionRisks = [];
    if (winner.sourceQuality.tier === 'unknown' || winner.sourceQuality.tier === 'lower') {
      rejectionRisks.push(`Source tier is ${winner.sourceQuality.tier}; manual verification recommended`);
    }
    if (!candidateRelevance.hasProfileSignal) {
      rejectionRisks.push('No candidate role/skill data was available to score relevance on this item');
    } else if (candidateRelevance.score < 50) {
      rejectionRisks.push(`Candidate relevance is moderate/low: ${candidateRelevance.note}`);
    }
    if (geography.tier === 'international' || geography.tier === 'unknown') {
      rejectionRisks.push(`Geography confidence is limited: ${geography.note}`);
    }
    if (freshness.score < 50) {
      rejectionRisks.push(`Freshness signal is weak: ${freshness.note}`);
    }
    if (contentQuality.score < 50) {
      rejectionRisks.push(`Content quality below optimal: ${contentQuality.note}`);
    }
    if (opportunityDetection.rejectReasons.length > 0) {
      rejectionRisks.push(
        `Some non-opportunity signals were present but outweighed by opportunity signals: ${opportunityDetection.rejectReasons.slice(0, 2).join('; ')}`
      );
    }

    survivors.push({
      query_id: safeString(raw.query_id),
      related_query_ids: multiQueryEvidence.map((e) => e.query_id).filter(Boolean),
      search_query: safeString(raw.search_query),
      discovery_type: safeString(raw.discovery_type),
      opportunity_type: opportunityDetection.inferredType,
      source_family: safeString(raw.source_family),
      source_quality_tier: winner.sourceQuality.tier,
      source_quality_score: winner.sourceQuality.score,
      search_priority: raw.search_priority !== undefined ? raw.search_priority : null,
      search_geography: safeString(raw.search_geography),
      candidate_city: safeString(raw.candidate_city),
      candidate_state: safeString(raw.candidate_state),
      candidate_country: safeString(raw.candidate_country),
      target_roles: toArrayField(raw.target_roles),
      candidate_skills: toArrayField(raw.candidate_skills),
      geography_policy: safeString(raw.geography_policy),
      title: safeString(raw.title),
      url: safeString(raw.url),
      canonical_url: winner.canonicalUrl || safeString(raw.canonical_url) || safeString(raw.url),
      content: safeString(raw.content),
      score: raw.score !== undefined ? raw.score : null,
      discovery_engine: safeString(raw.discovery_engine),
      discovered_at: safeString(raw.discovered_at),
      multi_query_evidence: multiQueryEvidence,
      discovery_count: clusterIndices.length,
      confidence_score: confidenceScore,
      confidence_breakdown: breakdown,
      acceptance_reasons: acceptanceReasons,
      rejection_risks: rejectionRisks,
      admission_tier: relaxed ? 'broadened' : 'primary'
    });
  } catch (err) {
    // A malformed item must never crash the whole batch; it is simply
    // excluded from the surviving set.
    return;
  }
});

  survivors.sort((a, b) => b.confidence_score - a.confidence_score);
  return survivors;
}

// Pass 1 — strict.
let admitted = admitClusters(false);
const primaryCount = admitted.length;
let broadeningApplied = false;

// Pass 2 — broadened, only if the first pass is too thin to plausibly yield 5.
if (primaryCount < BROADEN_IF_FEWER_THAN) {
  broadeningApplied = true;
  const relaxedAll = admitClusters(true);
  const seen = new Set(admitted.map((s) => s.canonical_url || s.url));
  for (const item of relaxedAll) {
    const key = item.canonical_url || item.url;
    if (seen.has(key)) continue;
    seen.add(key);
    admitted.push(item);
  }
  admitted.sort((a, b) => b.confidence_score - a.confidence_score);
}

admitted = admitted.slice(0, MAX_ADMITTED);

const broadenedCount = admitted.filter((s) => s.admission_tier === 'broadened').length;
console.log(
  `Discovery gate: ${primaryCount} admitted strictly` +
  (broadeningApplied
    ? `; broadening applied (below ${BROADEN_IF_FEWER_THAN}), +${broadenedCount} relaxed admissions`
    : '; broadening not needed') +
  `; ${admitted.length} total.`
);

// Carry the broadening decision downstream so the response can report whether
// broadening ran before any weak-resume conclusion is drawn.
admitted.forEach((s) => {
  s.discovery_broadening = {
    applied: broadeningApplied,
    primary_admitted: primaryCount,
    broadened_admitted: broadenedCount,
    threshold: BROADEN_IF_FEWER_THAN
