  finalUrl:          $json.finalUrl          ?? __src.finalUrl          ?? null,
  canonical_url:     $json.canonical_url     ?? __src.canonical_url     ?? __src.url ?? null,
  source_url:        $json.source_url        ?? __src.canonical_url     ?? __src.url ?? null,
  domain:            $json.domain            ?? __src.domain            ?? null,
  query_id:          $json.query_id          ?? __src.query_id          ?? null,
  discovery_type:    $json.discovery_type    ?? __src.discovery_type    ?? null,
  source_family:     $json.source_family     ?? __src.source_family     ?? null,
  search_geography:  $json.search_geography  ?? __src.search_geography  ?? null,
  candidate_city:    $json.candidate_city    ?? __src.candidate_city    ?? null,
  candidate_state:   $json.candidate_state   ?? __src.candidate_state   ?? null,
  candidate_country: $json.candidate_country ?? __src.candidate_country ?? null,
  discovered_title:  __src.title ?? null,
