/**
 * n8n Code Node: "Clean HTML"
 * -----------------------------------------------------------------------
 * Converts raw HTML (read from $json.data) into clean, readable plain
 * text using only built-in JavaScript (no cheerio/jsdom/npm packages).
 *
 * Mode: Run Once For Each Item
 *
 * Output shape:
 * [
 *   { json: { ...$json, clean_text } }
 * ]
 *
 * Design notes:
 * - Pure regex/string based pipeline (deterministic, sandbox-safe).
 * - Never throws: every stage is defensive against malformed/partial HTML.
 * - Static regexes are compiled once at module scope to avoid recompiling
 *   them on every invocation.
 * -----------------------------------------------------------------------
 */

// =============================================================
// STATIC CONFIG (compiled once)
// =============================================================

// Tags removed completely, including everything nested inside them.
const REMOVE_TAGS = [
  "script", "style", "noscript", "template", "svg", "canvas",
  "iframe", "object", "embed", "audio", "video",
  "form", "button", "select", "option"
];

// Layout/navigation tags removed completely, including their content.
const NAV_LAYOUT_TAGS = ["header", "footer", "nav", "aside"];

// Combined list used for the bulk "remove tag + content" pass.
const REMOVE_TAGS_ALL = REMOVE_TAGS.concat(NAV_LAYOUT_TAGS);

// Tags that should become paragraph breaks (structure-preserving).
const STRUCTURE_BREAK_TAGS = [
  "article", "section", "main", "div", "p", "blockquote", "li",
  "tr", "table", "thead", "tbody",
  "h1", "h2", "h3", "h4", "h5", "h6"
];

// Standard HTML void elements (never have a separate closing tag).
const VOID_ELEMENTS = new Set([
  "br", "hr", "img", "input", "meta", "link",
  "area", "base", "col", "embed", "source", "track", "wbr"
]);

// Class/id substrings that mark an element as noise to be removed.
const UNWANTED_KEYWORDS = [
  "cookie", "consent", "gdpr", "banner", "popup", "modal",
  "advertisement", "ads", "promo", "newsletter"
];

// Precompiled, reusable regexes.
const RE_COMMENT = /<!--[\s\S]*?-->/g;
const RE_DOCTYPE = /<!DOCTYPE[^>]*>/gi;
const RE_XML_DECL = /<\?xml[^>]*\?>/gi;
const RE_CDATA = /<!\[CDATA\[[\s\S]*?\]\]>/g;

const RE_STRUCTURE_BREAK = new RegExp(
  "<\\/?(?:" + STRUCTURE_BREAK_TAGS.join("|") + ")(?:\\s[^<>]*)?\\/?>",
  "gi"
);
const RE_LINE_BREAK_TAG = /<(?:br|hr)(?:\s[^<>]*)?\/?>/gi;
const RE_ANY_REMAINING_TAG = /<[^>]*>/g;

const RE_HIDDEN_BOOL_ATTR = /(^|\s)hidden(\s|=|\/|>|$)/i;

const RE_DECIMAL_ENTITY = /&#(\d+);/g;
const RE_HEX_ENTITY = /&#x([0-9a-fA-F]+);/g;
const RE_NAMED_ENTITY = /&([a-zA-Z][a-zA-Z0-9]*);/g;

const RE_HORIZONTAL_WHITESPACE = /[ \t\f\v\u00A0]+/g;
const RE_MULTI_BLANK_LINES = /\n{3,}/g;

// Any HTML opening tag (captures name, raw attribute string, self-close flag).
const RE_ANY_OPEN_TAG = /<([a-zA-Z][\w:-]*)((?:\s+[^<>]*?)?)(\/?)>/g;

// Curated set of the most common named HTML entities.
const NAMED_ENTITIES = {
  nbsp: "\u00A0", amp: "&", lt: "<", gt: ">", quot: '"', apos: "'",
  cent: "\u00A2", pound: "\u00A3", yen: "\u00A5", euro: "\u20AC",
  copy: "\u00A9", reg: "\u00AE", trade: "\u2122",
  sect: "\u00A7", para: "\u00B6", middot: "\u00B7",
  laquo: "\u00AB", raquo: "\u00BB", iexcl: "\u00A1", iquest: "\u00BF",
  deg: "\u00B0", plusmn: "\u00B1", times: "\u00D7", divide: "\u00F7",
  frac12: "\u00BD", frac14: "\u00BC", frac34: "\u00BE",
  sup2: "\u00B2", sup3: "\u00B3", micro: "\u00B5", ordm: "\u00BA", ordf: "\u00AA",
  hellip: "\u2026", mdash: "\u2014", ndash: "\u2013",
  lsquo: "\u2018", rsquo: "\u2019", ldquo: "\u201C", rdquo: "\u201D",
  bull: "\u2022", dagger: "\u2020", Dagger: "\u2021", permil: "\u2030",
  prime: "\u2032", Prime: "\u2033",
  larr: "\u2190", uarr: "\u2191", rarr: "\u2192", darr: "\u2193", harr: "\u2194",
  spades: "\u2660", clubs: "\u2663", hearts: "\u2665", diams: "\u2666",
  frasl: "\u2044", minus: "\u2212", lowast: "\u2217", radic: "\u221A",
  infin: "\u221E", ang: "\u2220", and: "\u2227", or: "\u2228",
  cap: "\u2229", cup: "\u222A", int: "\u222B", there4: "\u2234",
  sim: "\u223C", cong: "\u2245", asymp: "\u2248", ne: "\u2260",
  equiv: "\u2261", le: "\u2264", ge: "\u2265",
  sub: "\u2282", sup: "\u2283", nsub: "\u2284", sube: "\u2286", supe: "\u2287",
  oplus: "\u2295", otimes: "\u2297", perp: "\u22A5", sdot: "\u22C5",
  lceil: "\u2308", rceil: "\u2309", lfloor: "\u230A", rfloor: "\u230B",
  lang: "\u27E8", rang: "\u27E9", loz: "\u25CA",
  forall: "\u2200", part: "\u2202", exist: "\u2203", empty: "\u2205", nabla: "\u2207",
  isin: "\u2208", notin: "\u2209", ni: "\u220B", prod: "\u220F", sum: "\u2211",
  Agrave: "\u00C0", Aacute: "\u00C1", Acirc: "\u00C2", Atilde: "\u00C3", Auml: "\u00C4", Aring: "\u00C5", AElig: "\u00C6",
