// =============================================================
// GENERIC HELPERS
// =============================================================

/**
 * Safely converts a code point number into a character.
 * Returns an empty string for anything invalid instead of throwing.
 */
function codePointToChar(code) {
  if (!Number.isFinite(code) || code < 0 || code > 0x10FFFF) return "";
  try {
    return String.fromCodePoint(code);
  } catch (err) {
    return "";
  }
}

/**
 * Extracts the value of a single HTML attribute from a raw attribute
 * string, supporting double-quoted, single-quoted and unquoted values.
 * Returns null if the attribute is not present.
 */
function getAttrValue(attrString, attrName) {
  if (!attrString) return null;
  const re = new RegExp(
    attrName + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s"\'>]+))',
    "i"
  );
  const match = attrString.match(re);
  if (!match) return null;
  if (match[1] !== undefined) return match[1];
  if (match[2] !== undefined) return match[2];
  return match[3];
}

/**
 * Determines whether a tag (by its raw attribute string) matches the
 * "unwanted noise" criteria (cookie banners, ads, modals, etc.) or the
 * "hidden element" criteria (hidden attr, aria-hidden, inline display/
 * visibility styles).
 */
function isNoiseOrHiddenElement(attrString) {
  const classValue = (getAttrValue(attrString, "class") || "").toLowerCase();
  const idValue = (getAttrValue(attrString, "id") || "").toLowerCase();

  for (let i = 0; i < UNWANTED_KEYWORDS.length; i++) {
    const keyword = UNWANTED_KEYWORDS[i];
    if (classValue.includes(keyword) || idValue.includes(keyword)) return true;
  }

  if (RE_HIDDEN_BOOL_ATTR.test(attrString)) return true;

  const ariaHidden = getAttrValue(attrString, "aria-hidden");
  if (ariaHidden && ariaHidden.toLowerCase() === "true") return true;

  const styleValue = (getAttrValue(attrString, "style") || "")
    .toLowerCase()
    .replace(/\s+/g, "");
  if (styleValue.includes("display:none") || styleValue.includes("visibility:hidden")) {
    return true;
  }

  return false;
}

/**
 * Finds the index (exclusive end) of the closing tag that matches the
 * opening tag of `tagName` starting the search at `startPos`, correctly
 * accounting for nested tags of the same name. Returns -1 if no matching
 * close tag is found (caller treats the rest of the document as removed).
 */
function findMatchingCloseTagIndex(html, tagName, startPos) {
  const re = new RegExp("<(\\/?)" + tagName + "(?:\\s[^<>]*)?(\\/?)>", "gi");
  re.lastIndex = startPos;
  let depth = 1;
  let match;
  while ((match = re.exec(html)) !== null) {
    const isClosing = match[1] === "/";
    const isSelfClosing = match[2] === "/" || VOID_ELEMENTS.has(tagName);
    if (isClosing) {
      depth -= 1;
      if (depth === 0) return re.lastIndex;
    } else if (!isSelfClosing) {
      depth += 1;
    }
  }
  return -1;
}

// =============================================================
// PIPELINE STAGES
// =============================================================

/** Removes HTML comments, DOCTYPE declarations, XML declarations and CDATA. */
function stripNonContentMarkup(html) {
  return html
    .replace(RE_COMMENT, "")
    .replace(RE_DOCTYPE, "")
    .replace(RE_XML_DECL, "")
    .replace(RE_CDATA, "");
}

/**
 * Removes every occurrence of the given tag names, including everything
 * nested inside them, in a single left-to-right pass. Handles nesting of
 * the same tag name (e.g. <div><div>...</div></div>) and self-closing
 * variants gracefully, and never throws on malformed/unbalanced markup.
 */
function removeTagsWithContent(html, tagNames) {
  const namePattern = tagNames.join("|");
  const tagRe = new RegExp("<(\\/?)(" + namePattern + ")(?:\\s[^<>]*)?(\\/?)>", "gi");

  let result = "";
  let lastIndex = 0;
  let depth = 0;
  let activeTag = null;
  let match;

  while ((match = tagRe.exec(html)) !== null) {
    const closingSlash = match[1];
    const tagName = match[2].toLowerCase();
    const selfClose = match[3];
    const isClosing = closingSlash === "/";
    const isSelfClosing = selfClose === "/" || VOID_ELEMENTS.has(tagName);

    if (depth === 0) {
      // Not currently inside a removed block: keep the text before this tag.
      result += html.slice(lastIndex, match.index);
      if (!isClosing) {
        if (isSelfClosing) {
          // No content to skip; simply drop the tag itself.
          lastIndex = tagRe.lastIndex;
        } else {
          depth = 1;
          activeTag = tagName;
          lastIndex = tagRe.lastIndex;
        }
      } else {
        // Stray closing tag with no matching opener at this depth: drop it.
        lastIndex = tagRe.lastIndex;
      }
    } else if (tagName === activeTag) {
      // Only track depth for the tag name that started the current removal.
      if (isClosing) {
        depth -= 1;
        if (depth === 0) {
          lastIndex = tagRe.lastIndex;
          activeTag = null;
        }
      } else if (!isSelfClosing) {
        depth += 1;
      }
    }
    // Any other tag encountered while depth > 0 is part of the removed
    // subtree and is dropped along with everything else in that range.
  }

  // If we end mid-removal (unbalanced HTML), drop the unterminated tail.
  result += depth === 0 ? html.slice(lastIndex) : "";
  return result;
}

/**
 * Removes elements (any tag name) whose attributes mark them as cookie
 * banners, ads, popups/modals, newsletters, or hidden content, including
 * their full nested subtree.
 */
function removeNoiseAndHiddenElements(html) {
  let result = "";
  let lastIndex = 0;
  RE_ANY_OPEN_TAG.lastIndex = 0;
  let match;

  while ((match = RE_ANY_OPEN_TAG.exec(html)) !== null) {
    if (match.index < lastIndex) continue; // already inside a removed range

    const tagName = match[1].toLowerCase();
    const attrString = match[2] || "";
    const selfClose = match[3];

    if (!isNoiseOrHiddenElement(attrString)) continue;

    result += html.slice(lastIndex, match.index);

    if (selfClose === "/" || VOID_ELEMENTS.has(tagName)) {
      lastIndex = RE_ANY_OPEN_TAG.lastIndex;
    } else {
      const endIdx = findMatchingCloseTagIndex(html, tagName, RE_ANY_OPEN_TAG.lastIndex);
      lastIndex = endIdx !== -1 ? endIdx : html.length;
    }
    RE_ANY_OPEN_TAG.lastIndex = lastIndex;
  }

  result += html.slice(lastIndex);
  return result;
}

/** Converts structural block tags into paragraph breaks. */
function convertStructureToParagraphBreaks(html) {
  return html.replace(RE_STRUCTURE_BREAK, "\n\n");
}

/** Converts <br> and <hr> tags into single line breaks. */
function convertLineBreakTags(html) {
  return html.replace(RE_LINE_BREAK_TAG, "\n");
}

/** Fallback pass: strips any remaining HTML tags outright. */
function stripRemainingTags(html) {
  return html.replace(RE_ANY_REMAINING_TAG, "");
}

/** Decodes named, decimal and hexadecimal HTML entities, preserving Unicode. */
function decodeEntities(text) {
  return text
    .replace(RE_HEX_ENTITY, (_, hex) => codePointToChar(parseInt(hex, 16)))
    .replace(RE_DECIMAL_ENTITY, (_, dec) => codePointToChar(parseInt(dec, 10)))
    .replace(RE_NAMED_ENTITY, (fullMatch, name) => {
      if (Object.prototype.hasOwnProperty.call(NAMED_ENTITIES, name)) {
        return NAMED_ENTITIES[name];
      }
      const lower = name.toLowerCase();
      if (Object.prototype.hasOwnProperty.call(NAMED_ENTITIES, lower)) {
        return NAMED_ENTITIES[lower];
      }
      return fullMatch; // Unknown entity: leave untouched rather than guessing.
    });
}

/** Collapses runs of horizontal whitespace into single spaces. */
function collapseWhitespace(text) {
  return text.replace(RE_HORIZONTAL_WHITESPACE, " ");
}

/** Trims each line and collapses repeated blank lines down to one. */
function collapseBlankLines(text) {
  const trimmedLines = text
    .split("\n")
    .map(line => line.trim())
    .join("\n");
  return trimmedLines.replace(RE_MULTI_BLANK_LINES, "\n\n");
}

// =============================================================
// MAIN PIPELINE
// =============================================================

/**
 * Converts raw HTML into clean, readable plain text.
 * Defensive by design: never throws, always returns a string.
 */
function cleanHtml(rawHtml) {
  if (rawHtml === undefined || rawHtml === null) return "";

  let html;
  try {
    html = String(rawHtml);
  } catch (err) {
    return "";
  }

  if (html.trim() === "") return "";

  try {
    html = stripNonContentMarkup(html);
    html = removeTagsWithContent(html, REMOVE_TAGS_ALL);
    html = removeNoiseAndHiddenElements(html);
    html = convertStructureToParagraphBreaks(html);
    html = convertLineBreakTags(html);
    html = stripRemainingTags(html);

    let text = decodeEntities(html);
    text = collapseWhitespace(text);
    text = collapseBlankLines(text);

    return text.trim();
  } catch (err) {
    // Last-resort fallback: strip all tags and decode entities only,
    // guaranteeing the node never throws on malformed input.
    try {
      const fallback = decodeEntities(String(rawHtml).replace(RE_ANY_REMAINING_TAG, ""));
      return collapseBlankLines(collapseWhitespace(fallback)).trim();
    } catch (fallbackErr) {
      return "";
    }
  }
}

// =============================================================
// n8n NODE ENTRY POINT (Run Once For Each Item)
// =============================================================

// TWO upstream shapes reach this node, and only one of them was ever handled.
//
// HTTP Request1 (fast plain fetch, checked by "If" for Cloudflare/block
// markers) returns its body as $json.data — n8n's default for a non-JSON
// text response. But when "If" detects a block and routes through
// "playwright" (render-service, a real headless-browser render), that
// response is a JSON object whose HTML lives under $json.html, not $json.data
// — verified against render-service/src/routes/fetch.js, which never emits a
// field called "data".
//
// This node read ONLY $json.data, so every item that needed JS rendering
// arrived with rawHtmlInput = undefined, clean_text = '', and was later
// counted as "no readable job details" — a claim about the posting when the
// truth was a field-name mismatch on our side. Measured on a real run: 20 of
// 70 items took the playwright path and every one of them was lost this way.
// Confirmed independently that the pages themselves were fine — e.g.
// cutshort.io/job/... and job-boards.greenhouse.io/pay2dc/... both rendered
// successfully (status 200, jsRendered true, 100-900KB of real HTML) and were
// still skipped.
const rawHtmlInput = $json && ($json.data || $json.html);
const clean_text = cleanHtml(rawHtmlInput);

return {
    json: {
      ...$json,
      ...__provenance,
      clean_text
    }
  };

/**
 * ============================================================================
 * Extract Main Content — n8n Code Node
 * ----------------------------------------------------------------------------
 * Purpose:
 *   Convert cleaned webpage text ($json.clean_text) into the highest-quality
 *   textual representation of the PRIMARY opportunity (job/internship listing).
 *
 *   This node performs TEXT EXTRACTION ONLY. It does not classify, rank,
 *   summarize, or structure the content — that happens downstream.
 *
 * Input:
 *   $json.clean_text : string
 *
 * Output:
 *   {
 *     ...$json,
 *     main_content: string,
 *     extraction_meta: {
 *       confidence: number,
 *       started_by: string | null,
 *       stopped_by: string | null,
 *       blocks_seen: number,
 *       blocks_kept: number,
 *       duplicate_blocks_removed: number,
 *       evidence: {
 *         title_found: boolean,
 *         company_found: boolean,
 *         location_found: boolean,
 *         header_preserved: boolean,
 *         start_marker_found: boolean,
 *         stop_marker_found: boolean,
 *         responsibilities_found: boolean,
 *         requirements_found: boolean,
 *         skills_found: boolean,
 *         benefits_found: boolean,
 *         duplicate_ratio: number,
 *         useful_blocks: number,
 *         discarded_blocks: number
 *       }
 *     }
 *   }
 * ============================================================================
 */

// ============================================================================
// CONSTANTS
// ============================================================================

// Headings that plausibly mark the START of the real opportunity content.
// Matched case-insensitively against the start of a block (with optional
// punctuation like ":" or "-" following the word).
const START_HEADING_SIGNALS = [
  'about',
  'job description',
  'internship description',
  'overview',
  'internship',
  'role',
  'position',
  'responsibilities',
  'requirements',
  'qualifications',
  'skills',
  'eligibility',
  'benefits',
  'perks',
  'compensation',
  'location',
  'duration',
  'salary',
  'stipend',
];

// Keywords that indicate a block is relevant to the opportunity body and
// should be kept once we're inside the "collecting" phase.
const KEEP_SIGNALS = [
  'responsibilit',
  'requirement',
  'qualification',
  'skill',
  'benefit',
  'perk',
  'compensation',
  'company',
  'location',
  'duration',
  'salary',
  'stipend',
  'eligib',
  'apply',
];

// Headings/phrases that mark the END of the relevant content. Once seen,
// collection stops immediately (this and all subsequent blocks are dropped).
const STOP_SIGNALS = [
  'sponsored',
  'advertisement',
  'ads',
  'similar jobs',
  'related jobs',
  'related internships',
  'recommended jobs',
  'people also viewed',
  'more opportunities',
  'more jobs',
  'other openings',
  'featured jobs',
  'footer',
  'privacy policy',
  'terms',
  'contact us',
  'contact',
  'newsletter',
  'copyright',
  'social links',
  'follow us',
  'navigation',
  'search results',
  'cookie banner',
  'cookie policy',
  'cookies',
];

// Scoring weights for confidence calculation. Kept as named constants so
// tuning does not require touching the scoring logic itself.
// Positive signals sum to 1.00; negative signals are then subtracted as
// penalties, and the final score is clamped to [0, 1].
const SCORE_WEIGHTS = {
  START_FOUND: 0.08,
  STOP_FOUND: 0.06,
  SIZE: 0.10,
  HEADINGS: 0.08,
  KEEP_RATIO: 0.08,
  TITLE_DETECTED: 0.08,
  COMPANY_DETECTED: 0.08,
  LOCATION_DETECTED: 0.06,
  HEADER_PRESERVED: 0.04,
  RESPONSIBILITIES_FOUND: 0.06,
  REQUIREMENTS_FOUND: 0.06,
  SKILLS_FOUND: 0.06,
  BENEFITS_FOUND: 0.05,
  SECTION_DIVERSITY: 0.06,
  LOW_DUPLICATE_RATIO: 0.05,
};

// Penalties for negative evidence, subtracted from the positive total.
const SCORE_PENALTIES = {
  VERY_SHORT_EXTRACTION: 0.20,
  NO_START_DETECTED: 0.05,
  NO_STOP_DETECTED: 0.05,
  MOSTLY_LOW_VALUE: 0.10,
  EXCESSIVE_DUPLICATES: 0.10,
  LOW_KEEP_RATIO: 0.10,
};

// Thresholds used by the negative-signal checks above.
const VERY_SHORT_EXTRACTION_CHARS = 150;
const EXCESSIVE_DUPLICATE_RATIO = 0.30;
const LOW_KEEP_RATIO_THRESHOLD = 0.10;
const LOW_VALUE_CONTENT_RATIO_THRESHOLD = 0.30;

// Number of distinct recognized section headings considered "full credit"
// for the section-diversity signal.
const IDEAL_SECTION_DIVERSITY = 4;

// A block is considered "reasonably sized" content once it reaches this
// many characters; used to normalize the SIZE component of the score.
const IDEAL_CONTENT_LENGTH = 800;

// Minimum length for a block to be considered non-trivial (e.g. not just
// stray punctuation or a lone bullet character).
const MIN_BLOCK_LENGTH = 2;

// How many blocks immediately preceding a detected start heading are
// pulled in as "header" context (title, company, location, etc). This is
// intentionally small — the header is usually only a few short lines
// sitting right above the first real section heading.
const HEADER_LOOKBACK_BLOCKS = 3;

// Common legal-entity suffixes used to heuristically recognize a company
// name inside the preserved header region.
const COMPANY_SUFFIX_PATTERN = /\b(inc|llc|ltd|pvt\.?\s*ltd|limited|corp|corporation|technologies|solutions|systems|labs|group)\b/i;

// Signals used to heuristically recognize a LOCATION line: explicit work
// mode words, or a short "City, Region" style comma pattern.
const LOCATION_MODE_PATTERN = /\b(remote|hybrid|on[\s-]?site|work from home|wfh)\b/i;
const LOCATION_COMMA_PATTERN = /^[A-Z][\p{L}.'\s]+,\s*[A-Z][\p{L}.'\s]+$/u;

// Standalone UI/navigation phrases (calls-to-action, nav links) that carry
// no extraction value on their own. Matched only against a block's FULL
// normalized text — never against a substring — so a sentence like
// "Apply React and JavaScript..." is never affected.
const CTA_UI_PHRASES = new Set([
  'apply',
  'apply now',
  'register',
  'register now',
  'login',
  'log in',
  'sign in',
  'sign up',
  'bookmark',
  'save',
  'share',
  'read more',
  'view more',
  'show more',
  'back',
  'next',
  'previous',
  'menu',
  'search',
]);

// Trailing decorative characters (arrows, chevrons, punctuation) stripped
// before comparing a block against CTA_UI_PHRASES.
const CTA_TRAILING_SYMBOLS_PATTERN = /[\s\-–—»›»>→▶.!?…]+$/;

// Shared patterns used inside per-block loops. Hoisted to module scope so
// they are compiled once, not re-created on every function call.
const HEADING_TRAILING_COLON_PATTERN = /[:：]\s*$/;
const TERMINAL_PUNCTUATION_PATTERN = /[.!?]\s*$/;
const WHITESPACE_COLLAPSE_PATTERN = /\s+/g;

// ============================================================================
// PREPROCESSING
// ============================================================================

/**
 * Normalize Unicode and whitespace so downstream matching is reliable.
 * - NFKC normalization collapses visually-identical Unicode variants.
 * - Non-breaking spaces and similar are converted to regular spaces.
 * - Windows/Mac line endings are normalized to \n.
 */
function normalizeText(raw) {
  if (typeof raw !== 'string') return '';

  let text = raw.normalize('NFKC');

  // Normalize various space-like characters to a plain space.
  text = text.replace(/[\u00A0\u2000-\u200B\u202F\u205F\u3000]/g, ' ');

  // Normalize line endings.
  text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

  // Collapse runs of horizontal whitespace (not newlines) to a single space.
  text = text.replace(/[ \t\f\v]+/g, ' ');

  // Collapse 3+ consecutive newlines down to exactly 2 (preserve paragraph
  // breaks, but avoid excessive blank space).
  text = text.replace(/\n{3,}/g, '\n\n');

  return text.trim();
}

/**
 * Split normalized text into logical blocks (roughly: paragraphs / lines).
 * A block boundary is a blank line OR a single newline — single newlines
 * are treated as soft breaks within the same "unit" only when the line
 * itself looks like a continuation (no strong signal either way is treated
 * as a boundary to keep blocks small and analyzable).
 *
 * Empty / whitespace-only blocks are discarded here.
 */
function splitIntoBlocks(text) {
  if (!text) return [];

  // Split on one-or-more blank lines first (paragraph-level split).
  const paragraphChunks = text.split(/\n\s*\n/);

  const blocks = [];
  for (const chunk of paragraphChunks) {
    // Within a paragraph chunk, also split on single newlines so headings
    // that sit on their own line are treated as distinct blocks.
    const lines = chunk.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.length >= MIN_BLOCK_LENGTH) {
        blocks.push(trimmed);
      }
    }
  }

  return blocks;
}

// ============================================================================
// HEADING DETECTION
// ============================================================================

/**
 * Returns true if a block reads like a short heading line (as opposed to a
 * full sentence/paragraph) — short, no terminal punctuation, or ends with
 * a colon.
 */
function looksLikeHeading(block) {
  if (block.length > 60) return false;
  if (HEADING_TRAILING_COLON_PATTERN.test(block)) return true;
  if (!TERMINAL_PUNCTUATION_PATTERN.test(block)) return true;
  return false;
}

/**
 * Returns true if `ch` is an ASCII letter or digit. Used for lightweight
 * word-boundary checks without paying for a regex per call.
 */
function isAlphanumericChar(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9');
}

/**
 * True if `text` starts with `signal` AND the character immediately
 * following it is not itself alphanumeric (or the match runs to the end
 * of the string). This prevents partial-word false positives such as
 * "Roleplay" matching the signal "role", or "Adsense" matching "ads".
 */
function startsWithWholeWordSignal(text, signal) {
  if (!text.startsWith(signal)) return false;
  const nextChar = text.charAt(signal.length);
  return nextChar === '' || !isAlphanumericChar(nextChar);
}

/**
 * True if `text` ends with `signal` AND the character immediately
 * preceding it is not itself alphanumeric (or the match starts at the
 * beginning of the string). Lets short qualified headings like
 * "Company Footer" or "Site Navigation" still be recognized as
 * boilerplate sections, without risking a substring match mid-sentence.
 */
function endsWithWholeWordSignal(text, signal) {
  if (!text.endsWith(signal)) return false;
  const precedingIndex = text.length - signal.length - 1;
  return precedingIndex < 0 || !isAlphanumericChar(text.charAt(precedingIndex));
}

/**
 * Finds which (if any) start-signal keyword this block matches, checked
 * against the beginning of the block text.
 * Returns the matched signal string, or null.
 */
function matchStartSignal(blockLower) {
  for (const signal of START_HEADING_SIGNALS) {
    if (startsWithWholeWordSignal(blockLower, signal)) {
      return signal;
    }
  }
  return null;
}

/**
 * Finds which (if any) stop-signal keyword this block matches. Checked
 * against both the beginning (e.g. "Footer") and the end (e.g. "Company
 * Footer", "Site Navigation") of the block text, since boilerplate
 * headings are commonly qualified with a preceding label. Stop headings
 * are short section titles (call sites also require looksLikeHeading),
 * so this stays precise without risking catastrophic regex backtracking
 * — it uses plain string operations, no regex.
 * Returns the matched signal string, or null.
 */
function matchStopSignal(blockLower) {
  for (const signal of STOP_SIGNALS) {
    if (startsWithWholeWordSignal(blockLower, signal) || endsWithWholeWordSignal(blockLower, signal)) {
      return signal;
    }
  }
  return null;
}

/**
 * Returns true if the block contains any of the "keep" relevance keywords
 * anywhere in its text (substring match — these are body-relevance cues,
 * not strict headings).
 */
function containsKeepSignal(blockLower) {
  for (const signal of KEEP_SIGNALS) {
    if (blockLower.includes(signal)) {
      return true;
    }
  }
  return false;
}

/**
 * Heuristic: does this block look like a job/internship TITLE line?
 * Short, no terminal sentence punctuation, and not itself a recognized
 * section heading (titles precede headings, they aren't one).
 */
function looksLikeTitle(block) {
  if (block.length === 0 || block.length > 80) return false;
  if (matchStartSignal(block.toLowerCase())) return false;
  if (TERMINAL_PUNCTUATION_PATTERN.test(block)) return false;
  return true;
}

/**
 * Heuristic: does this block look like a COMPANY name? Matches a common
 * legal-entity suffix (Inc, LLC, Technologies, etc). This is intentionally
 * conservative — false negatives are fine, false positives are not.
 */
function looksLikeCompany(block) {
  return COMPANY_SUFFIX_PATTERN.test(block);
}

/**
 * Heuristic: does this block look like a LOCATION line? Either an explicit
 * work-mode word (remote/hybrid/onsite) or a short "City, Region" pattern.
 */
function looksLikeLocation(block) {
  if (block.length > 60) return false;
  return LOCATION_MODE_PATTERN.test(block) || LOCATION_COMMA_PATTERN.test(block);
}

// ============================================================================
// START DETECTION
// ============================================================================

/**
 * Scans blocks for the best candidate start index using weighted signals:
 *   - A heading-shaped block matching a start signal is the strongest cue.
 *   - A non-heading block that merely contains a keep-signal is a weaker,
 *     fallback cue, used only if no strong heading match is found.
 *
 * Returns { index, matchedBy } where index is the block index to start
 * collecting FROM (inclusive), and matchedBy is the signal text (or null
 * if no start was detected, in which case we default to the beginning).
 */
function detectStart(blocks) {
  let fallbackIndex = -1;
  let fallbackSignal = null;

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];
    const blockLower = block.toLowerCase();
    const isHeading = looksLikeHeading(block);

    // A block that reads as a boilerplate/navigational heading (footer,
    // privacy policy, cookie banner, navigation, etc) must never be
    // treated as the opportunity start, even if it happens to contain a
    // keep-signal word (e.g. "Company Footer" contains "company").
    if (isHeading && matchStopSignal(blockLower)) {
      continue;
    }

    const strongMatch = matchStartSignal(blockLower);
    if (strongMatch && isHeading) {
      return { index: i, matchedBy: strongMatch };
    }

    if (fallbackIndex === -1 && containsKeepSignal(blockLower)) {
      fallbackIndex = i;
      fallbackSignal = 'keyword-context';
    }
  }

  if (fallbackIndex !== -1) {
    return { index: fallbackIndex, matchedBy: fallbackSignal };
  }

  // No signal found at all — default to collecting from the top.
  return { index: 0, matchedBy: null };
}

/**
 * Given the index of a detected start heading, returns the index to begin
 * collection FROM so that the immediately preceding "opportunity header"
 * (title, company, location, mode, duration, salary, openings, etc) is
 * preserved rather than discarded.
 *
 * Only applied when the start was matched by a real heading signal — the
 * generic 'keyword-context' fallback has no reliable heading boundary to
 * look back from, so no header is pulled in for that case.
 *
 * Always clamped to >= 0; never produces a negative index.
 */
function computeHeaderStartIndex(startIndex, startedBy) {
  if (!startedBy || startedBy === 'keyword-context') {
    return startIndex;
  }
  return Math.max(0, startIndex - HEADER_LOOKBACK_BLOCKS);
}

// ============================================================================
// STOP DETECTION
// ============================================================================

/**
 * Scans blocks (starting from startIndex) for the first block that matches
 * a stop signal. Returns { index, matchedBy } where index is the block
 * index at which collection must stop (exclusive — this block and all
 * after it are dropped). If no stop signal is found, index is blocks.length
 * (i.e. collect through the end) and matchedBy is null.
 */
function detectStop(blocks, startIndex) {
  for (let i = startIndex; i < blocks.length; i++) {
    const blockLower = blocks[i].toLowerCase();
    const stopMatch = matchStopSignal(blockLower);

    if (stopMatch && looksLikeHeading(blocks[i])) {
      return { index: i, matchedBy: stopMatch };
    }
  }

  return { index: blocks.length, matchedBy: null };
}

// ============================================================================
// DUPLICATE REMOVAL
// ============================================================================

/**
 * Removes blocks that are exact duplicates (after case-insensitive,
 * whitespace-normalized comparison) of a block already kept earlier in
 * the sequence. Preserves original order of first occurrence.
 *
 * Returns { deduped, removedCount }.
 */
function removeDuplicateBlocks(blocks) {
  const seen = new Set();
  const deduped = [];
  let removedCount = 0;

  for (const block of blocks) {
    const key = block.toLowerCase().replace(WHITESPACE_COLLAPSE_PATTERN, ' ').trim();

    if (seen.has(key)) {
      removedCount++;
      continue;
    }

    seen.add(key);
    deduped.push(block);
  }

  return { deduped, removedCount };
}

// ============================================================================
// CTA / UI FILTERING
// ============================================================================

/**
 * Normalizes a block for CTA comparison: lowercase, trailing decorative
 * symbols stripped, whitespace collapsed. Only the FULL normalized block
 * is ever compared — this is intentional, so CTA words used naturally
 * inside a real sentence are never touched.
 */
function normalizeForCtaMatch(block) {
  return block
    .toLowerCase()
    .replace(CTA_TRAILING_SYMBOLS_PATTERN, '')
    .replace(WHITESPACE_COLLAPSE_PATTERN, ' ')
    .trim();
}

/**
 * Returns true only when a block's ENTIRE normalized text is a known
 * standalone UI/navigation phrase (e.g. "Apply Now", "Read More →").
 * A block that merely contains one of these words as part of a longer
 * sentence will never match, since the comparison is a full-string
 * equality against the CTA set, not a substring test.
 */
function isStandaloneCtaBlock(block) {
  return CTA_UI_PHRASES.has(normalizeForCtaMatch(block));
}

/**
 * Removes standalone CTA/navigation blocks from the kept region. O(n),
 * single pass, Set-backed lookup.
 */
function filterCtaBlocks(blocks) {
  return blocks.filter((block) => !isStandaloneCtaBlock(block));
}

// ============================================================================
// QUALITY SCORING
// ============================================================================

/**
 * Computes a 0.00..1.00 confidence score for the extraction from explicit
 * positive and negative evidence, AND returns that same evidence as a set
 * of deterministic, explainable flags/counts — so the score is no longer
 * opaque. The evidence values are read directly off the signals already
 * computed during scoring; nothing here changes extraction behaviour or
 * the score formula itself.
 *
 * Positive:
 *   - title / company / location detected anywhere in the retained
 *     content, header preserved
 *   - clear start / stop heading detected
 *   - content size relative to an "ideal" length
 *   - density of useful headings, section diversity
 *   - ratio of kept blocks vs. total blocks seen, low duplicate ratio
 *   - responsibilities / requirements / skills / benefits sections found
 *
 * Negative:
 *   - very short extraction
 *   - no clear start / no clear stop heading found
 *   - mostly low-value content within the kept region
 *   - excessive duplicate removal
 *   - very low useful-content ratio
 *
 * Returns { confidence, evidence }.
 */
function computeConfidence({
  startedBy,
  stoppedBy,
  keptBlocks,
  totalBlocksSeen,
  keptContentLength,
  headerPreserved,
  titleDetected,
  companyDetected,
  locationDetected,
  duplicatesRemoved,
}) {
  let score = 0;

  // --- Positive signals ---
  if (startedBy) score += SCORE_WEIGHTS.START_FOUND;
  if (stoppedBy) score += SCORE_WEIGHTS.STOP_FOUND;

  const sizeRatio = Math.min(keptContentLength / IDEAL_CONTENT_LENGTH, 1);
  score += sizeRatio * SCORE_WEIGHTS.SIZE;

  // Compute each block's lowercase text and heading-shape once, and reuse
  // it across every pass below instead of recomputing per-check.
  const blockInfo = keptBlocks.map((b) => ({
    lower: b.toLowerCase(),
    isHeading: looksLikeHeading(b),
  }));

  const headingInfo = blockInfo.filter((info) => info.isHeading);
  const usefulHeadingCount = headingInfo.filter(
    (info) => matchStartSignal(info.lower) || containsKeepSignal(info.lower)
  ).length;
  const headingRatio = Math.min(usefulHeadingCount / 5, 1); // 5+ useful headings = full credit
  score += headingRatio * SCORE_WEIGHTS.HEADINGS;

  const keepRatio = totalBlocksSeen > 0 ? keptBlocks.length / totalBlocksSeen : 0;
  score += keepRatio * SCORE_WEIGHTS.KEEP_RATIO;

  if (titleDetected) score += SCORE_WEIGHTS.TITLE_DETECTED;
  if (companyDetected) score += SCORE_WEIGHTS.COMPANY_DETECTED;
  if (locationDetected) score += SCORE_WEIGHTS.LOCATION_DETECTED;
  if (headerPreserved) score += SCORE_WEIGHTS.HEADER_PRESERVED;

  const joinedLower = blockInfo.map((info) => info.lower).join(' ');
  const responsibilitiesFound = joinedLower.includes('responsibilit');
  const requirementsFound = joinedLower.includes('requirement');
  const skillsFound = joinedLower.includes('skill');
  const benefitsFound = joinedLower.includes('benefit') || joinedLower.includes('perk');
  if (responsibilitiesFound) score += SCORE_WEIGHTS.RESPONSIBILITIES_FOUND;
  if (requirementsFound) score += SCORE_WEIGHTS.REQUIREMENTS_FOUND;
  if (skillsFound) score += SCORE_WEIGHTS.SKILLS_FOUND;
  if (benefitsFound) score += SCORE_WEIGHTS.BENEFITS_FOUND;

  // Section diversity: how many DISTINCT recognized section headings
  // (not just how many heading blocks) appear in the kept region.
  const distinctSections = new Set(
    headingInfo.map((info) => matchStartSignal(info.lower)).filter((signal) => signal !== null)
  );
  const diversityRatio = Math.min(distinctSections.size / IDEAL_SECTION_DIVERSITY, 1);
  score += diversityRatio * SCORE_WEIGHTS.SECTION_DIVERSITY;

  // Low duplicate ratio: full credit at zero duplicates, tapering to zero
  // credit at/after the "excessive" threshold.
  const totalConsidered = keptBlocks.length + duplicatesRemoved;
  const duplicateRatio = totalConsidered > 0 ? duplicatesRemoved / totalConsidered : 0;
  const lowDuplicateCredit = Math.max(0, 1 - duplicateRatio / EXCESSIVE_DUPLICATE_RATIO);
  score += lowDuplicateCredit * SCORE_WEIGHTS.LOW_DUPLICATE_RATIO;

  // --- Negative signals (penalties) ---
  if (keptContentLength < VERY_SHORT_EXTRACTION_CHARS) {
    score -= SCORE_PENALTIES.VERY_SHORT_EXTRACTION;
  }

  if (!startedBy) {
    score -= SCORE_PENALTIES.NO_START_DETECTED;
  }

  if (!stoppedBy) {
    score -= SCORE_PENALTIES.NO_STOP_DETECTED;
  }

  // Composition of the kept region itself: what fraction of kept blocks
  // are actually useful (a heading, or containing a keep-relevance cue)?
  const usefulBlockCount = blockInfo.filter(
    (info) => info.isHeading || containsKeepSignal(info.lower)
  ).length;
  const usefulContentRatio = keptBlocks.length > 0 ? usefulBlockCount / keptBlocks.length : 0;
  if (usefulContentRatio < LOW_VALUE_CONTENT_RATIO_THRESHOLD) {
    score -= SCORE_PENALTIES.MOSTLY_LOW_VALUE;
  }

  if (duplicateRatio > EXCESSIVE_DUPLICATE_RATIO) {
    score -= SCORE_PENALTIES.EXCESSIVE_DUPLICATES;
  }

  if (keepRatio < LOW_KEEP_RATIO_THRESHOLD) {
    score -= SCORE_PENALTIES.LOW_KEEP_RATIO;
  }

  // Clamp to [0, 1] and round to 2 decimal places for a clean, stable
  // output value that is always between 0.00 and 1.00.
  score = Math.max(0, Math.min(1, score));
  const confidence = Math.round(score * 100) / 100;

  // Explainable evidence: the same deterministic signals used above,
  // exposed directly rather than folded only into the opaque score.
  const evidence = {
    title_found: titleDetected,
    company_found: companyDetected,
    location_found: locationDetected,
    header_preserved: headerPreserved,
    start_marker_found: Boolean(startedBy),
    stop_marker_found: Boolean(stoppedBy),
    responsibilities_found: responsibilitiesFound,
    requirements_found: requirementsFound,
    skills_found: skillsFound,
    benefits_found: benefitsFound,
    duplicate_ratio: Math.round(duplicateRatio * 100) / 100,
    useful_blocks: usefulBlockCount,
    discarded_blocks: Math.max(0, totalBlocksSeen - keptBlocks.length),
  };

  return { confidence, evidence };
}

// ============================================================================
// METADATA VALIDATION
// ============================================================================

/**
 * Neutral/zeroed evidence used whenever extraction did not run far enough
 * to produce real signals (empty input) or hit the safety-net error path.
 */
const NEUTRAL_EVIDENCE = {
  title_found: false,
  company_found: false,
  location_found: false,
  header_preserved: false,
  start_marker_found: false,
  stop_marker_found: false,
  responsibilities_found: false,
  requirements_found: false,
  skills_found: false,
  benefits_found: false,
  duplicate_ratio: 0,
  useful_blocks: 0,
  discarded_blocks: 0,
};

/**
 * Defensively validates the evidence object's shape: booleans stay
 * booleans, counts/ratios are finite and non-negative (ratio additionally
 * clamped to [0, 1]). Falls back to NEUTRAL_EVIDENCE field-by-field for
 * anything malformed, so evidence can never reach the caller in a shape
 * that doesn't match the documented schema.
 */
function validateEvidence(evidence) {
  const e = evidence || {};
  const asBoolean = (v) => v === true;
  const asNonNegativeInt = (v) => (Number.isFinite(v) ? Math.max(0, Math.round(v)) : 0);

  return {
    title_found: asBoolean(e.title_found),
    company_found: asBoolean(e.company_found),
    location_found: asBoolean(e.location_found),
    header_preserved: asBoolean(e.header_preserved),
    start_marker_found: asBoolean(e.start_marker_found),
    stop_marker_found: asBoolean(e.stop_marker_found),
    responsibilities_found: asBoolean(e.responsibilities_found),
    requirements_found: asBoolean(e.requirements_found),
    skills_found: asBoolean(e.skills_found),
    benefits_found: asBoolean(e.benefits_found),
    duplicate_ratio: Number.isFinite(e.duplicate_ratio) ? Math.max(0, Math.min(1, e.duplicate_ratio)) : 0,
    useful_blocks: asNonNegativeInt(e.useful_blocks),
    discarded_blocks: asNonNegativeInt(e.discarded_blocks),
  };
}

/**
 * Defensive final check that the output metadata satisfies its documented
 * invariants, regardless of how it was computed upstream:
 *   - 0 <= blocks_kept <= blocks_seen
 *   - 0 <= duplicate_blocks_removed
 *   - confidence is a finite number in [0, 1]
 *   - started_by / stopped_by are either a string or null
 *   - evidence matches its documented shape (see validateEvidence)
 * This never changes correct output; it only clamps/guards against an
 * unexpected upstream value so malformed metadata can never reach the
 * caller.
 */
function validateMeta(meta) {
  const blocksSeen = Number.isFinite(meta.blocks_seen) && meta.blocks_seen >= 0 ? meta.blocks_seen : 0;
  const blocksKept = Number.isFinite(meta.blocks_kept)
    ? Math.max(0, Math.min(meta.blocks_kept, blocksSeen))
    : 0;
  const duplicatesRemoved = Number.isFinite(meta.duplicate_blocks_removed)
    ? Math.max(0, meta.duplicate_blocks_removed)
    : 0;
  const confidence = Number.isFinite(meta.confidence) ? Math.max(0, Math.min(1, meta.confidence)) : 0;
  const startedBy = typeof meta.started_by === 'string' ? meta.started_by : null;
  const stoppedBy = typeof meta.stopped_by === 'string' ? meta.stopped_by : null;

  return {
    confidence,
    started_by: startedBy,
    stopped_by: stoppedBy,
    blocks_seen: blocksSeen,
    blocks_kept: blocksKept,
    duplicate_blocks_removed: duplicatesRemoved,
    evidence: validateEvidence(meta.evidence),
  };
}

// ============================================================================
// OUTPUT ASSEMBLY
// ============================================================================

/**
 * Joins kept blocks back into readable text. Heading-shaped blocks get a
 * blank line before them (except at the very start) to preserve visual
 * section structure; regular blocks are joined with single newlines within
 * a run, and a blank line separates distinct paragraphs/sections.
 */
function assembleOutputText(blocks) {
  const lines = [];

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];
    const isHeading = looksLikeHeading(block);

    if (i > 0 && isHeading) {
      lines.push(''); // blank line before a new section heading
    }

    lines.push(block);
  }

  return lines.join('\n').trim();
}

// ============================================================================
// MAIN PIPELINE
// ============================================================================

function extractMainContent(rawInput) {
  // --- Preprocessing ---
  const normalized = normalizeText(rawInput);
  const allBlocks = splitIntoBlocks(normalized);
  const blocksSeen = allBlocks.length;

  if (blocksSeen === 0) {
    return {
      mainContent: '',
      meta: validateMeta({
        confidence: 0,
        started_by: null,
        stopped_by: null,
        blocks_seen: 0,
        blocks_kept: 0,
        duplicate_blocks_removed: 0,
        evidence: NEUTRAL_EVIDENCE,
      }),
    };
  }

  // --- Start detection ---
  const start = detectStart(allBlocks);

  // --- Header preservation: pull in a small look-back window of blocks
  // immediately preceding the detected start heading, so the opportunity
  // header (title, company, location, mode, duration, salary, openings,
  // employment type) isn't discarded. Safe against negative indexes.
  const headerStartIndex = computeHeaderStartIndex(start.index, start.matchedBy);
  const headerBlocks = allBlocks.slice(headerStartIndex, start.index);
  const headerPreserved = headerBlocks.length > 0;

  // --- Stop detection (search only after the start point) ---
  const stop = detectStop(allBlocks, start.index);

  // --- Slice the relevant region (header + body) ---
  const rawKeptBlocks = allBlocks.slice(headerStartIndex, stop.index);

  // --- Duplicate removal ---
  const { deduped, removedCount } = removeDuplicateBlocks(rawKeptBlocks);

  // --- CTA / UI filtering (standalone nav/action blocks only — text
  // occurring naturally inside real sentences is left untouched) ---
  const contentBlocks = filterCtaBlocks(deduped);

  // --- Output assembly ---
  const mainContent = assembleOutputText(contentBlocks);

  // --- Title/company/location evidence: checked against every block that
  // actually made it into main_content (not just the header look-back
  // window), so a flag can only be false when the signal is truly absent
  // from the extracted text. ---
  const titleDetected = contentBlocks.some(looksLikeTitle);
  const companyDetected = contentBlocks.some(looksLikeCompany);
  const locationDetected = contentBlocks.some(looksLikeLocation);

  // --- Quality scoring (confidence + explainable evidence) ---
  const { confidence, evidence } = computeConfidence({
    startedBy: start.matchedBy,
    stoppedBy: stop.matchedBy,
    keptBlocks: contentBlocks,
    totalBlocksSeen: blocksSeen,
    keptContentLength: mainContent.length,
    headerPreserved,
    titleDetected,
    companyDetected,
    locationDetected,
    duplicatesRemoved: removedCount,
  });

  return {
    mainContent,
    meta: validateMeta({
      confidence,
      started_by: start.matchedBy,
      stopped_by: stop.matchedBy,
      blocks_seen: blocksSeen,
      blocks_kept: contentBlocks.length,
      duplicate_blocks_removed: removedCount,
      evidence,
    }),
  };
}

// ============================================================================
// N8N NODE ENTRY POINT
// ============================================================================

// Null-safe access: if the upstream node didn't set clean_text (or $json
// itself is unexpectedly missing/malformed), fall back to an empty string
// rather than throwing.
const inputText = ($json && typeof $json.clean_text === 'string') ? $json.clean_text : '';

// The pipeline is defensively coded to handle empty/whitespace/malformed
// input without throwing, but this try/catch is a last-resort safety net:
// this node must never fail the workflow, even on a truly unexpected
// runtime error. On failure it returns the same output shape with neutral,
// schema-valid metadata rather than propagating the error.
let result;
try {
  result = extractMainContent(inputText);
} catch (err) {
  result = {
    mainContent: '',
    meta: validateMeta({
      confidence: 0,
      started_by: null,
      stopped_by: null,
      blocks_seen: 0,
      blocks_kept: 0,
      duplicate_blocks_removed: 0,
      evidence: NEUTRAL_EVIDENCE,
    }),
  };
}

return {
  ...$json,
  main_content: result.mainContent,
  extraction_meta: result.meta,
};

// Merge the extracted fields ONTO the item, never replace it.
//
// This node used to return the LLM's output alone, which discarded the source
// URL the page was fetched from (url / finalUrl / source_url). The effect was a
// perfect inversion, measured on a real run: the 7 items where extraction
// SUCCEEDED (and so had company and description) lost their URL and were then
// excluded by product rule 5, while the items that survived rule 5 were exactly
// the ones where extraction had been skipped and had no company or description.
// Every returned opportunity therefore had company = null.
//
// The source URL is always known — it is what we fetched — so it must never be
// lost to an extraction step.

// $json here is whatever the previous node emitted. On the extraction branch
// that is the ai-gateway RESPONSE ({success, requestId, data}) — HTTP Request2
// replaced the item, so the source URL is NOT on $json. Reach back to the last
// node that still had it, by paired item.
let source = $json || {};
if (!source.url && !source.source_url) {
  try {
    const upstream = $('guard node').item.json;
    if (upstream && (upstream.url || upstream.source_url)) source = { ...upstream, ...source };
  } catch (e) {
    // Paired-item lookup unavailable (e.g. replayed offline) — fall back to
    // whatever $json carries rather than failing the item.
  }
}

// Carry-through fields that identify the posting itself and can never come
// from the extracted body.
const provenance = {
  url: source.url ?? null,
  finalUrl: source.finalUrl ?? null,
  source_url: source.source_url ?? null,
  canonical_url: source.canonical_url ?? null,
  domain: source.domain ?? null,
  query_id: source.query_id ?? null,
  discovery_type: source.discovery_type ?? null,
  source_family: source.source_family ?? null,
  search_geography: source.search_geography ?? null,
  candidate_city: source.candidate_city ?? null,
  candidate_state: source.candidate_state ?? null,
  candidate_country: source.candidate_country ?? null,
  extraction_skipped: source.extraction_skipped ?? false,
  skip_reason: source.skip_reason ?? null,
};

function merged(extracted) {
  const out = { ...provenance, ...extracted };
  // An extracted applicationUrl is preferred, but the page we actually fetched
  // is the reliable fallback — it is by definition a real, reachable posting.
  out.application_url =
    extracted.applicationUrl || extracted.application_url ||
    provenance.url || provenance.finalUrl || provenance.source_url || null;
  return out;
}

// Every exit records HOW extraction ended, per item.
//
// Until now the last line returned the item with no extracted fields and NO
// marker, so an item whose extraction call failed was indistinguishable
// downstream from a page that genuinely had nothing on it — hasScorableContent
// saw empty fields either way and counted both as skipped_no_content. That is
// reported to the student as a property of the POSTING ("no readable job
// details"), so our own failure was being presented as a fact about the world.
//
// Measured cause for suspecting this: 12 skipped items were resolved back to
// their URLs and fetched — jobs.lever.co/palantir and apply.workable.com/
// robusta both returned real, readable job content (7,469 and 7,982 cleaned
// chars, correct titles) and were still skipped. The pages were fine.
//
// extraction_status is diagnostic only; nothing branches on it yet. Read it
// from a run before deciding whether pacing or more keys is the fix.
const url = provenance.url || provenance.finalUrl || provenance.source_url || null;

if ($json.data && typeof $json.data === 'object') {
  console.log('extraction ok        ' + url);
  return { json: { ...merged($json.data), extraction_status: 'extracted' } };
}
if ($json.text) {
  try {
    const parsed = JSON.parse($json.text);
    console.log('extraction ok(text)  ' + url);
    return { json: { ...merged(parsed), extraction_status: 'extracted_from_text' } };
  } catch (e) {
    // The model answered but not with JSON. Distinct from never answering.
    console.log('extraction UNPARSED  ' + url + ' — ' + e.message);
    return {
      json: {
        ...provenance,
        error: e.message,
        raw: $json.text,
        extraction_status: 'parse_failed'
      }
    };
  }
}
// Neither data nor text: the gateway returned nothing usable — a 4xx/5xx, an
// exhausted provider chain, or a timeout. THIS is the silent path that was
// masquerading as an empty posting.
// Two very different things end up here, and conflating them cost a whole
// wrong diagnosis: an item the guard node never SENT (clean_text and
// main_content both empty or under MIN_CONTENT_LENGTH), versus one that was
// sent and came back unusable. Reading the gateway log settled which is which:
// 58 requests, all status 200 — the gateway was never the problem, the items
// simply never reached it.
if (provenance.extraction_skipped) {
  console.log('extraction NOT SENT   ' + url + ' — guard: ' + (provenance.skip_reason || 'no reason recorded'));
  return { json: { ...source, extraction_status: 'guard_skipped' } };
}
console.log('extraction NO RESPONSE ' + url + ' — keys: ' + Object.keys($json || {}).join(','));
return { json: { ...source, extraction_status: 'no_response' } };

const job = JSON.parse(JSON.stringify($json && typeof $json === "object" ? $json : {}));

// -------------------------
// Helpers
// -------------------------

const PLACEHOLDER_VALUES = new Set(["", "-", "n/a", "na", "null", "undefined"]);

/** Trims a string; passes any non-string value through unchanged. */
const trim = (v) => (typeof v === "string" ? v.trim() : v);

/** Trims a string and converts it to null if empty or a placeholder value. */
const cleanString = (v) => {
  const t = trim(v);
  if (typeof t !== "string") return t == null ? null : t;
  return PLACEHOLDER_VALUES.has(t.toLowerCase()) ? null : t;
};

/** Trims a URL and converts it to null if empty or a placeholder value. Never alters a real URL. */
const cleanUrl = (v) => cleanString(v);

/** Coerces any value into an array: arrays pass through, everything else becomes []. */
const toArray = (v) => (Array.isArray(v) ? v : []);

/** Converts a value to a finite number, or null if it isn't one. Never returns NaN. */
const toNumberOrNull = (v) => {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

/**
 * Cleans an array-ish field: coerces non-arrays to [], drops null/empty/
 * placeholder entries, trims strings, and removes duplicates case-
 * insensitively (first-seen casing wins) while preserving original order.
 */
const unique = (arr) => {
  const seen = new Set();
  const result = [];
  for (const item of toArray(arr)) {
    if (item === null || item === undefined) continue;
    const str = trim(String(item));
    if (str.length === 0 || PLACEHOLDER_VALUES.has(str.toLowerCase())) continue;
    const key = str.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(str);
  }
  return result;
};

const normalizeWorkMode = (mode) => {
  const cleaned = cleanString(mode);
  if (!cleaned) return null;
  const m = cleaned.toLowerCase();
  if (m.includes("remote")) return "Remote";
  if (m.includes("hybrid")) return "Hybrid";
  if (m.includes("office") || m.includes("onsite") || m.includes("on-site")) {
    return "On-site";
  }
  return cleaned;
};

const normalizeEmploymentType = (type) => {
  const cleaned = cleanString(type);
  if (!cleaned) return null;
  const t = cleaned.toLowerCase();
  if (t.includes("intern")) return "Internship";
  if (t.includes("full")) return "Full-time";
  if (t.includes("part")) return "Part-time";
  if (t.includes("contract")) return "Contract";
  if (t.includes("freelance")) return "Freelance";
  return cleaned;
};

const SKILL_MAP = {
  reactjs: "React",
  "react.js": "React",
  react: "React",
  javascript: "JavaScript",
  "java script": "JavaScript",
  typescript: "TypeScript",
  "type script": "TypeScript",
  node: "Node.js",
  nodejs: "Node.js",
  "node.js": "Node.js",
  html5: "HTML",
  css3: "CSS",
  gitlab: "Git",
  github: "Git",
};

/**
 * Normalizes a skills list: maps known aliases to their canonical name
 * (case-insensitive lookup, canonical casing preserved), trims anything
 * unmapped as-is, then deduplicates case-insensitively so unmapped skills
 * that only differ by casing (e.g. "Python" / "python") don't survive as
 * separate entries.
 */
const normalizeSkills = (skills) => {
  const mapped = toArray(skills)
    .filter((s) => s !== null && s !== undefined)
    .map((skill) => {
      const str = trim(String(skill));
      const key = str.toLowerCase();
      return SKILL_MAP[key] || str;
    });
  return unique(mapped);
};

/** Converts a salary amount to its monthly equivalent based on its period. Returns null if amount is null. */
const toMonthlyAmount = (amount, period) => {
  if (amount === null || amount === undefined) return null;
  const p = cleanString(period);
  const periodLower = p ? p.toLowerCase() : "";
  if (periodLower.includes("year") || periodLower.includes("annual")) return amount / 12;
  if (periodLower.includes("week")) return amount * (52 / 12);
  if (periodLower.includes("day")) return amount * (365 / 12);
  if (periodLower.includes("hour")) return amount * (365 / 12) * 8;
  return amount; // already monthly, or period unspecified/unrecognized
};

// -------------------------
// String fields: trim + blank/placeholder -> null
// -------------------------

[
  "title",
  "company",
  "description",
  "deadline",
].forEach((key) => {
  job[key] = cleanString(job[key]);
});

// -------------------------
// URL fields: trim + blank/placeholder -> null
// -------------------------

["application_url", "official_company_url"].forEach((key) => {
  job[key] = cleanUrl(job[key]);
});

// -------------------------
// Normalize fields
// -------------------------

job.work_mode = normalizeWorkMode(job.work_mode);
job.employment_type = normalizeEmploymentType(job.employment_type);
job.required_skills = normalizeSkills(job.required_skills);
job.preferred_skills = normalizeSkills(job.preferred_skills);
job.technologies = normalizeSkills(job.technologies);

// -------------------------
// Clean arrays
// -------------------------

job.education_requirements = unique(job.education_requirements);
job.eligibility = unique(job.eligibility);
job.benefits = unique(job.benefits);
job.selection_process = unique(job.selection_process);

// -------------------------
// Salary cleanup
// -------------------------

const salary = (job.salary && typeof job.salary === "object" && !Array.isArray(job.salary))
  ? job.salary
  : null;

if (salary) {
  salary.min = toNumberOrNull(salary.min);
  salary.max = toNumberOrNull(salary.max);
}

// -------------------------
// Derived fields
// -------------------------

const loc = job.location || {};
const city = cleanString(loc.city);
const state = cleanString(loc.state);
const country = cleanString(loc.country);
const locationDisplay = [city, state, country].filter(Boolean).join(", ") || null;
job.location = {
  city: city ?? null,
  state: state ?? null,
  country: country ?? null,
  display: locationDisplay,
};

// A disclosed salary can arrive either as a structured {min, max} object or
// as a plain string (e.g. from providers that don't structure pay). is_paid
// reflects disclosure either way; salary_monthly only exists when numeric
// bounds are available to convert.
const salaryDisclosedAsString = !salary && typeof job.salary === "string" && cleanString(job.salary) !== null;
// TRISTATE, not boolean. A disclosed salary -> true. But "no salary found"
// is NOT the same as "unpaid", and returning false for it told students an
// internship was unpaid when nobody established that — the same fabrication
// class that got nine ingestion providers deleted. So: true when pay is
// disclosed, null when nothing was found. Never a bare false here.
const _payDisclosed = !!(salary && (salary.min !== null || salary.max !== null)) || salaryDisclosedAsString;
job.is_paid = _payDisclosed ? true : null;

job.salary_monthly = salary
  ? {
      min: toMonthlyAmount(salary.min, salary.period),
      max: toMonthlyAmount(salary.max, salary.period),
    }
  : null;

job.search_keywords = unique([
  ...job.required_skills,
  ...job.preferred_skills,
  ...job.technologies,
]);

job.schema_version = "standardize-v1";
job.pipeline = {
  stage: "standardize",
  version: "1.0.0",
  processed_at: new Date().toISOString(),
};

return {
    json: job,
  };

// Scores every item in the current batch.
//
// This node stays in "Run Once for All Items" mode deliberately: it needs
// $('Code in JavaScript').first() for the candidate profile, and n8n forbids
// .first() in per-item mode. Iterating $input.all() also lets one batch's
// scoring calls run concurrently instead of serially.

const candidate = $('Code in JavaScript').first().json.candidate || {};
const items = $input.all();

// Only the fields that actually inform a fit score are sent to the model.
//
// Measured live: standardized opportunities ranged from 1.2KB to 1.18MB
// (~294k tokens) because `raw` carries the whole scraped page. Groq's limit is
// 12k tokens per minute, so the oversized payloads returned HTTP 400 and drove
// an 80% scoring failure rate. Projecting the payload is what fixes that — the
// bulk was never useful for scoring.
const MAX_DESCRIPTION_CHARS = 4000;
const MAX_LIST_ITEMS = 25;

function toScoringPayload(opp) {
  const trim = (v) => (typeof v === 'string' ? v.slice(0, MAX_DESCRIPTION_CHARS) : v ?? null);
  const list = (v) => (Array.isArray(v) ? v.slice(0, MAX_LIST_ITEMS) : []);
  return {
    title:           opp.title ?? null,
    company:         opp.company ?? null,
    description:     trim(opp.description),
    requirements:    list(opp.requirements),
    skills:          list(opp.skills),
    location:        opp.location ?? null,
    work_mode:       opp.work_mode ?? null,
    employment_type: opp.employment_type ?? null,
    is_paid:         opp.is_paid ?? null,
    salary:          opp.salary ?? null,
  };
}

async function scoreOne(opportunity) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://localhost:4000/api/ai/chat',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': $env.GATEWAY_API_KEY
      },
      body: { task: 'score_fit', input: { candidate, opportunity: toScoringPayload(opportunity) } },
      json: true
    });

    opportunity.score = response.data.fit_score;
    opportunity.scoring_status = 'scored';
    opportunity.scoring_error = null;
    opportunity.reasoning = response.data.reasoning;
    opportunity.missing_requirements = response.data.missing_requirements;
  } catch (error) {
    const code = error?.response?.body?.error?.code
      || error?.cause?.error?.code
      || error?.error?.error?.code
      || error?.code
      || 'UNKNOWN_ERROR';
    console.log('AI Gateway scoring failed for opportunity:', opportunity.title, '-', code, '-', error.message);
    // A failed score is NOT a low score: leave score null so it can never be
    // ranked, allocated, or counted toward the honest total.
    opportunity.score = null;
    opportunity.scoring_status = 'failed';
    opportunity.scoring_error = code;
    opportunity.reasoning = null;
    opportunity.missing_requirements = null;
  }
  return opportunity;
}

// An item with no company, no description and no requirements gives the model
// nothing to match on. Measured on a real run: 16 of 22 scored items had none
// of the three, and 15 of those 16 scored exactly 0 — then fell below the
// score floor and were discarded. That is ~30% of a run's entire token budget
// spent to produce zeros.
//
// Skipping them is NOT the same as a scoring failure: the distinction task-1
// exists to protect is preserved by giving these their own status, so they can
// never be read as "scored low" or as a provider error.
function hasScorableContent(opp) {
  const nonEmpty = (v) => v !== null && v !== undefined && v !== '' &&
    !(Array.isArray(v) && v.length === 0);
  return nonEmpty(opp.company) || nonEmpty(opp.description) ||
         nonEmpty(opp.requirements) || nonEmpty(opp.skills);
}

const scorer = scoreOne.bind(this);

// Scored SEQUENTIALLY, deliberately. Measured live: Promise.all over a batch of
// 5 drove Groq into rate limiting and produced an 85.7% scoring failure rate
// (6/7, all PROVIDER_TRANSIENT_FAILURE inside a 400ms window), versus 1.8% when
// paced. Gemini cannot absorb the overflow — its configured model returns 404
// ("no longer available to new users") — so Groq is the only live provider and
// there is no fallback to catch a burst.
//
// Batching still pays off: the expensive part of the loop is page scraping,
// which n8n parallelises across the batch independently of this node.
const scored = [];
let skippedNoContent = 0;
for (const item of items) {
  const opp = item.json;
  if (!hasScorableContent(opp)) {
    opp.score = null;
    // Distinguish OUR failure from a genuinely empty posting. Both reach here
    // with the same empty fields, but they are not the same thing and must
    // never be reported to a student the same way — skipped_no_content is
    // shown as "the page had no job details", a claim about the world.
    // extraction_status is set by the JSON Parse node on every exit.
    opp.scoring_status =
      (opp.extraction_status === 'no_response' || opp.extraction_status === 'parse_failed')
        ? 'extraction_failed'
        : 'skipped_no_content';
    opp.scoring_error = null;
    opp.reasoning = null;
    opp.missing_requirements = null;
    skippedNoContent += 1;
    scored.push(opp);
    continue;
  }
  scored.push(await scorer(opp));
}
if (skippedNoContent > 0) {
  console.log(`Skipped scoring for ${skippedNoContent} item(s) with no company, description, requirements or skills — nothing to match on.`);
}

return scored.map(json => ({ json }));

// Get all processed opportunities. Resume Match Engine tags every item with
// scoring_status ('scored' or 'failed') - failed items carry score: null and must
// never be ranked or counted as a match.
const results = $input.all();

const scored = results.filter(r => r.json.scoring_status === 'scored' && typeof r.json.score === 'number');
const failed = results.filter(r => r.json.scoring_status !== 'scored');

// Sort by score (highest first). Only scored items participate in ranking.
scored.sort((a, b) => (b.json.score || 0) - (a.json.score || 0));

// 'skipped_no_content' is a THIRD outcome, distinct from both success and
// failure: we chose not to spend a scoring call on an item with nothing to
// match on. Counting it as failed would overstate provider problems; counting
// it as scored-low would be the exact conflation task-1 exists to prevent.
const skipped = results.filter(r => r.json.scoring_status === 'skipped_no_content');
// extraction_failed is OUR failure to read a real page (render 500, no
// response), NOT a thin posting and NOT a scoring-provider error. Count it on
// its own so Build Response can describe it truthfully instead of blaming the
// posting or the scoring provider.
const extractionFailed = results.filter(r => r.json.scoring_status === 'extraction_failed');
const summary = {
  attempted: results.length,
  succeeded: scored.length,
  failed: failed.length - skipped.length - extractionFailed.length,
  skipped_no_content: skipped.length,
  extraction_failed: extractionFailed.length
};

if (failed.length > 0) {
  console.log(`Scoring run summary: ${summary.succeeded}/${summary.attempted} succeeded, ${summary.failed} failed to score (excluded from results, not counted as low scores).`);
}

// Keep only Top 20 successfully-scored opportunities
const top20 = scored.slice(0, 20);

// If nothing scored successfully, the run-level summary must STILL reach the
// output. Returning an empty list here would erase the difference between
// "no opportunities were found" and "N were found but every score failed" —
// the exact conflation this task exists to prevent.
if (top20.length === 0) {
  return [{ json: { opportunities: [], scoring_summary: summary } }];
}

// Carry the run-level scoring summary through to the final output on every item.
top20.forEach(item => { item.json.scoring_summary = summary; });

return top20;

/**
 * ============================================================================
 * Content Guard — n8n Code Node
 * ----------------------------------------------------------------------------
 * Purpose:
 *   Sits between "Extract Main Content" and the LLM extraction call
 *   (HTTP Request2). Prevents empty/unusable extracted content from ever
 *   being sent to the LLM as a prompt (which causes a 400 error).
 *
 *   Uses the real field names produced by "Extract Main Content":
 *     - clean_text        (primary extracted text)
 *     - main_content       (secondary/alternate extracted text)
 *     - extraction_meta    (rich diagnostic object, includes blocks_kept,
 *                           header_preserved, start_marker_found, etc.)
 *
 *   A page is treated as SKIPPED (extraction_skipped = true) if either:
 *     a) both clean_text and main_content are empty/too short, OR
 *     b) extraction_meta explicitly reports zero useful blocks were kept
 *        (blocks_kept === 0) — this is a stronger, more reliable signal
 *        than text length alone, since it comes directly from the
 *        extractor's own accounting rather than a guessed threshold.
 *
 *   This node never throws. On any unexpected shape it defaults to
 *   SKIPPED (safe default — never sends a possibly-empty prompt to the LLM).
 * ============================================================================
 */

const MIN_CONTENT_LENGTH = 50; // below this, treat as unusable regardless of blocks_kept

function safeString(value) {
  if (typeof value === "string") return value;
  if (value === null || value === undefined) return "";
  return String(value);
}

function evaluateItem(rawItem) {
  const item = (rawItem && typeof rawItem === "object") ? rawItem : {};

  const cleanText = safeString(item.clean_text).trim();
  const mainContent = safeString(item.main_content).trim();

  // Prefer clean_text, fall back to main_content, never fall back to raw `data`
  // (raw HTML is always non-empty and would defeat the guard entirely).
  const bestContent = cleanText.length > 0 ? cleanText : mainContent;

  const meta = (item.extraction_meta && typeof item.extraction_meta === "object")
    ? item.extraction_meta
    : {};

  const blocksKept = Number.isFinite(meta.blocks_kept) ? meta.blocks_kept : null;
  const headerPreserved = meta.header_preserved === true;
  const startMarkerFound = meta.start_marker_found === true;
  const stopMarkerFound = meta.stop_marker_found === true;

  const reasons = [];

  const tooShort = bestContent.length < MIN_CONTENT_LENGTH;
  if (tooShort) {
    reasons.push(`extracted content is only ${bestContent.length} chars (min ${MIN_CONTENT_LENGTH})`);
  }

  const zeroBlocksKept = blocksKept === 0;
  if (zeroBlocksKept) {
    reasons.push("extraction_meta.blocks_kept is 0 (extractor found nothing usable)");
  }

  // Additional weak signal, not decisive on its own: neither header nor any
  // marker was found. Only escalates to a skip reason if content is ALSO short,
  // so a page that's short by design (e.g. a terse posting) but has a valid
  // header/marker isn't wrongly skipped.
  const noStructuralSignal = !headerPreserved && !startMarkerFound && !stopMarkerFound;
  if (noStructuralSignal && tooShort) {
    reasons.push("no header/start/stop marker found in source page structure");
  }

  const shouldSkip = tooShort || zeroBlocksKept;

  return {
    shouldSkip,
    reasons,
    bestContentLength: bestContent.length,
    blocksKept,
  };
}

// ============================================================================
// N8N NODE ENTRY POINT
// ============================================================================

try {
  const item = $json;
  const result = evaluateItem(item);

  return {
    json: {
      ...item,
      extraction_skipped: result.shouldSkip,
      skip_reason: result.shouldSkip
        ? result.reasons.join("; ")
        : null,
      guard_diagnostics: {
        best_content_length: result.bestContentLength,
        blocks_kept: result.blocksKept,
      },
      source_url: item.source_url || item.url || null,
    }
  };
} catch (err) {
  // Fail safe: if anything unexpected happens, skip rather than risk
  // sending a broken/empty prompt to the LLM.
  return {
    json: {
      ...($json || {}),
      extraction_skipped: true,
      skip_reason: `Guard node error: ${err && err.message ? err.message : "unknown error"}`,
      guard_diagnostics: null,
      source_url: ($json && ($json.source_url || $json.url)) || null,
    }
  };
}

// ============================================================
// GEOGRAPHIC ALLOCATOR
// ============================================================
// Allocates scored opportunities across geographic tiers.
//
// Two rules matter here:
//   1. Quality floor — a low-scoring item is never shown just to reach 10.
//      Geographic WIDENING is kept (pulling real, well-scored opportunities
//      from wider buckets is desirable); only junk is excluded.
//   2. `tier` is strictly geographic. "backfilled" was previously emitted as
//      a fourth tier value, which no consumer of the contract expects. The
//      widening signal now lives in `allocation_reason` instead.
// ============================================================

// Minimum fit score for an opportunity to be shown at all.
// Judgment call: below ~50 the match is not useful to a student, and showing
// it costs more trust than the extra row is worth. Tunable in one place.
const MIN_ALLOCATION_SCORE = 50;

const TARGET_COUNT = 10;
const MIN_USEFUL_COUNT = 5;

// Retrieve candidate profile from earlier node
const candidate = $('Code in JavaScript').first().json.candidate || {};
const candLoc = candidate.location || {};

const allItems = $input.all().map(item => item.json);

// Carry the run-level scoring summary through untouched.
const scoringSummary =
  allItems.find(o => o && o.scoring_summary)?.scoring_summary || null;

// Only genuinely-scored items are eligible. A failed score is not a low score
// and must never be allocated, backfilled, or counted toward the honest total.
const scored = allItems.filter(
  opp => opp.scoring_status === 'scored' && typeof opp.score === 'number'
);

// ---- Product rule 5: every apply URL must point to a specific live posting ----
// Measured across four real runs: of 10 reported opportunities, 4-5 had NO apply
// URL at all and 2-4 were aggregator/search/listing pages. Those are not
// opportunities a student can apply to, so they are excluded rather than counted.
// This lowers the returned count honestly instead of padding it with junk.

const AGGREGATOR_URL = /\/q-|\/jobs?\/[a-z-]*(jobs|internships)|\/jobs?\/[a-z0-9-]+\/(jobs|internships)\b|\/(internships|vacancies|openings)\/?$|linkedin\.com\/jobs\/[a-z]|indeed\.com\/q-|\/browse|search\?|naukri\.com\/[a-z-]+-jobs|internshala\.com\/internships\/?$|\/category\/[^\/]*\/?$|\/(join-us|join-our-team|careers?|work-with-us|we-are-hiring|opportunities)\/?$/i;
// Titles like "1,000+ Frontend Intern jobs in India" or "Find 58 internships".
const LISTING_TITLE  = /^\s*[\d,]+\+?\s|jobs and vacan|vacancies in|find \d+|\d+\s+internships?\b/i;

function applyUrlOf(opp) {
  return opp.application_url || opp.applicationUrl || opp.url || opp.finalUrl || opp.source_url || null;
}

function isSpecificPosting(opp) {
  const url = applyUrlOf(opp);
  if (!url) return false;
  if (AGGREGATOR_URL.test(url)) return false;
  if (LISTING_TITLE.test(String(opp.title || ''))) return false;
  return true;
}

// Apply the quality floor. Tracked separately so the output can report how
// many real matches existed versus how many cleared the bar.
const aboveFloor  = scored.filter(opp => opp.score >= MIN_ALLOCATION_SCORE);
const belowFloor  = scored.length - aboveFloor.length;

const eligible    = aboveFloor.filter(isSpecificPosting);
const excludedNoApplyUrl = aboveFloor.filter(o => !applyUrlOf(o)).length;
const excludedAggregator = aboveFloor.length - eligible.length - excludedNoApplyUrl;

// Normalise the apply URL onto a single canonical field for the contract.
for (const opp of eligible) opp.apply_url = applyUrlOf(opp);

function allocateGeographicDistribution(opportunities, candidateLocation) {
  const buckets = {
    same_state: [],
    same_country: [],
    international: [],
    unresolved_location: []
  };

  const candState = (candidateLocation?.state || '').trim().toLowerCase();
  const candCountry = (candidateLocation?.country || '').trim().toLowerCase();

  // 1. Bucket opportunities
  for (const opp of opportunities) {
    const oppState = (opp.state || (opp.location && opp.location.state) || '').trim().toLowerCase();
    const oppCountry = (opp.country || (opp.location && opp.location.country) || '').trim().toLowerCase();

    if (!oppCountry && !oppState) {
      buckets.unresolved_location.push(opp);
    } else if (oppCountry && candCountry && oppCountry !== candCountry) {
      buckets.international.push(opp);
    } else if (oppCountry === candCountry && oppState === candState && candState && oppState) {
      buckets.same_state.push(opp);
    } else if (oppCountry === candCountry && oppState !== candState) {
      buckets.same_country.push(opp);
    } else {
      buckets.unresolved_location.push(opp);
    }
  }

  // 2. Sort buckets by score descending
  const sortByScore = (a, b) => (b.overall_score || b.score || 0) - (a.overall_score || a.score || 0);
  for (const key of Object.keys(buckets)) buckets[key].sort(sortByScore);

  const allocated = [];

  // Pull top N from a bucket. `tier` is always the geographic bucket the item
  // actually came from; `allocation_reason` records whether it filled its own
  // quota or was pulled in while widening.
  const pull = (bucketName, count, reason) => {
    if (count <= 0) return;
    const pulled = buckets[bucketName].splice(0, count);
    for (const item of pulled) {
      item.tier = bucketName;
      item.allocation_reason = reason;
    }
    allocated.push(...pulled);
  };

  // 3. Initial allocation against the geographic target shape.
  pull('same_state', 7, 'quota');
  pull('same_country', 2, 'quota');
  pull('international', 1, 'quota');

  // 4. Widen to reach the target — real scored opportunities from wider
  //    buckets, all of which already cleared the score floor.
  const needed = () => TARGET_COUNT - allocated.length;
  pull('same_state', needed(), 'widened');
  pull('same_country', needed(), 'widened');
  pull('international', needed(), 'widened');
  pull('unresolved_location', needed(), 'widened');

  allocated.sort(sortByScore);
  return allocated;
}

const allocated = allocateGeographicDistribution(eligible, candLoc);

// Honest quota status — never "full" unless genuinely full of qualifying items.
let quota_status;
if (allocated.length >= TARGET_COUNT) {
  quota_status = 'full';
} else if (allocated.length >= MIN_USEFUL_COUNT) {
  quota_status = 'partial';
} else {
  quota_status = 'insufficient';
}

const sameStateCount = allocated.filter(o => o.tier === 'same_state').length;
const geographicTargetMet = sameStateCount >= 7;

// geographic_target_met alone was misleading: it demands 7 same-state results,
// which is unreachable whenever the list is short — so it read as "geography is
// broken" even when bucketing worked perfectly. What a caller actually needs to
// know is whether we could place each result on the map at all.
const resolvedCount = allocated.filter(o => o.tier !== 'unresolved_location').length;
const geographyResolved = allocated.length > 0
  ? Math.round((resolvedCount / allocated.length) * 100)
  : null;

const allocationSummary = {
  returned: allocated.length,
  target: TARGET_COUNT,
  quota_status,
  scored_candidates: scored.length,
  below_score_floor: belowFloor,
  excluded_no_apply_url: excludedNoApplyUrl,
  excluded_aggregator_page: excludedAggregator,
  min_score: MIN_ALLOCATION_SCORE,
  geographic_target_met: geographicTargetMet,
  geography_resolved_pct: geographyResolved,
  same_state: sameStateCount,
  scoring: scoringSummary
};

// Nothing to return is a legitimate outcome; do not fabricate rows.
if (allocated.length === 0) {
  return [{
    json: {
      opportunities: [],
      allocation_summary: allocationSummary,
      quota_status
    }
  }];
}

return allocated.map(opp => {
  opp.quota_status = quota_status;
  opp.allocation_summary = allocationSummary;
  return { json: opp };
});

// ============================================================
// BUILD RESPONSE
// ============================================================
// Produces the final service response and decides between the normal path
// and the weak-resume path.
//
// Gap feedback is aggregated ONLY over successfully-scored opportunities.
// If half the scoring failed to rate limits, aggregating across the whole
// set would tell a strong candidate their resume is weak because a provider
// throttled us — false, discouraging feedback that is worse than none.
// ============================================================

const MIN_USEFUL_COUNT = 5;

// A gap must appear in at least this many postings to be reported. One
// mention is noise, not a pattern.
const MIN_GAP_FREQUENCY = 2;

// The scoring model sometimes reports missing SCHEMA FIELDS rather than
// missing candidate skills ("job description", "location", "workplace type").
// Those describe a thin posting, not a gap in the resume, and must never be
// shown to a student as something they lack.
const SCHEMA_ARTIFACT_TERMS = new Set([
  'job description', 'description', 'required skills', 'requirements',
  'location', 'workplace type', 'employment type', 'employment type details',
  'salary', 'compensation', 'deadline', 'company', 'title', 'none',
  'not specified', 'n/a', 'unknown', 'experience', 'qualifications'
]);

const allocatorItems = $input.all().map(i => i.json);

// The allocator emits an explicit empty carrier when nothing qualified.
const isEmptyCarrier =
  allocatorItems.length === 1 && Array.isArray(allocatorItems[0].opportunities);

const opportunities = isEmptyCarrier ? [] : allocatorItems;

const allocationSummary =
  (isEmptyCarrier ? allocatorItems[0].allocation_summary : opportunities[0]?.allocation_summary) || {};

const scoringSummary = allocationSummary.scoring || null;

// Successfully-scored pool, for gap aggregation.
let scoredPool = [];
try {
  scoredPool = $('Finalize Results').all()
    .map(i => i.json)
    .filter(o => o && o.scoring_status === 'scored');
} catch (e) {
  scoredPool = [];
}

function canonicalGap(raw) {
  let g = String(raw || '').trim().toLowerCase();
  if (!g) return null;
  // Drop parenthetical examples: "ml frameworks (e.g. pytorch)" -> "ml frameworks"
  g = g.replace(/\s*\((?:e\.?g\.?|i\.?e\.?)[^)]*\)/g, '').trim();
  g = g.replace(/\s+/g, ' ').replace(/[.,;:]+$/, '').trim();
  if (!g || g.length < 2 || g.length > 60) return null;
  if (SCHEMA_ARTIFACT_TERMS.has(g)) return null;
  return g;
}

function aggregateGaps(pool) {
  const counts = new Map();
  // Canonical (lowercased) keys are used for counting, but student-facing copy
  // must show the skill as written — "Docker, AWS, and TypeScript", not
  // "docker, aws, and typescript".
  const display = new Map();
  let contributing = 0;

  for (const opp of pool) {
    const reqs = Array.isArray(opp.missing_requirements) ? opp.missing_requirements : [];
    if (reqs.length === 0) continue;
    contributing += 1;
    // Count each gap at most once per posting.
    const seen = new Set();
    for (const raw of reqs) {
      const g = canonicalGap(raw);
      if (!g || seen.has(g)) continue;
      seen.add(g);
      counts.set(g, (counts.get(g) || 0) + 1);
      if (!display.has(g)) {
        const asWritten = String(raw).trim().replace(/\s*\((?:e\.?g\.?|i\.?e\.?)[^)]*\)/g, '').trim();
        display.set(g, asWritten || g);
      }
    }
  }

  const gaps = [...counts.entries()]
    .filter(([, n]) => n >= MIN_GAP_FREQUENCY)
    .sort((a, b) => b[1] - a[1])
    .map(([skill, n]) => ({
      skill,
      label: display.get(skill) || skill,
      postings_requiring: n,
      of_postings_analyzed: contributing,
      message: `${n} of ${contributing} relevant roles wanted ${display.get(skill) || skill}, which your resume doesn't show.`
    }));

  return { gaps, postings_analyzed: contributing };
}

const { gaps, postings_analyzed } = aggregateGaps(scoredPool);

// Broadening happens at discovery time, BEFORE scoring. Surfacing it here lets
// a caller (and the tests) verify the required ordering: broaden first, and
// only conclude "weak profile" after broadening has already been tried.
let discoveryBroadening = null;
try {
  const gated = $('Discovery Quality Gate + Dedup').all().map(i => i.json);
  discoveryBroadening = (gated.find(g => g && g.discovery_broadening) || {}).discovery_broadening || null;
} catch (e) {
  discoveryBroadening = null;
}

// ---- Result tiering -------------------------------------------------------
// A short list is a CORRECT outcome, not a failure — provided the student is
// told why and what to do about it. We never pad to reach a tier.
//
//   8-10  results only, no warning
//   5-7   results + optional light suggestions
//   3-4   results + clear resume-strength message
//   1-2   results + strong message
//   0     no results + what to build first
const count = opportunities.length;

function tierFor(n) {
  if (n >= 8) return { tier: 'full',        strength: 'strong',     warn: false };
  if (n >= 5) return { tier: 'good',        strength: 'strong',     warn: 'light' };
  if (n >= 3) return { tier: 'limited',     strength: 'moderate',   warn: 'clear' };
  if (n >= 1) return { tier: 'very_limited', strength: 'needs_work', warn: 'strong' };
  return       { tier: 'none',              strength: 'needs_work', warn: 'strong' };
}
const { tier, strength: resumeStrength, warn } = tierFor(count);

// Feedback must be built from REAL aggregated evidence. When we have no
// evidence we say so plainly rather than dressing generic advice up as
// analysis.
function topGapPhrase(list, max) {
  const names = list.slice(0, max).map((g) => g.label || g.skill);
  if (names.length === 0) return null;
  if (names.length === 1) return names[0];
  if (names.length === 2) return `${names[0]} and ${names[1]}`;
  return `${names.slice(0, -1).join(', ')}, and ${names[names.length - 1]}`;
}

function buildFeedback() {
  const evidence = topGapPhrase(gaps, 3);
  const analysed = postings_analyzed;

  // A scoring outage is OUR failure and must never be framed as a weak resume.
  const scoringBroke = scoringSummary && scoringSummary.failed > 0 &&
    scoringSummary.failed >= scoringSummary.succeeded;
  if (scoringBroke) {
    return `We could not score ${scoringSummary.failed} of ${scoringSummary.attempted} matches ` +
           `because of a temporary problem on our side, so this list is shorter than it should be. ` +
           `Please try again shortly — this is not a reflection of your resume.`;
  }

  if (tier === 'full') return null;

  if (tier === 'good') {
    return evidence
      ? `Good match rate. To reach even more internships, consider adding ${evidence} — ` +
        `these came up in the roles you matched.`
      : `Good match rate. Adding a deployed project or an internship to your resume ` +
        `typically widens the range of roles you match.`;
  }

  if (tier === 'limited') {
    return evidence
      ? `Your resume matched a limited number of internships. Most of the roles you came ` +
        `close to wanted ${evidence} — adding one of these, ideally shown through a ` +
        `deployed project, should noticeably improve your matches.`
      : `Your resume matched a limited number of internships. Adding one or two concrete, ` +
        `deployed projects and naming the specific technologies you used in them is the ` +
        `fastest way to improve your matches.`;
  }

  if (tier === 'very_limited') {
    return evidence
      ? `Your resume is currently limiting your matches. The roles you came closest to ` +
        `wanted ${evidence}. Building one substantial project that uses ${evidence} — and ` +
        `describing what you built and deployed — should make a clear difference.`
      : `Your resume is currently limiting your matches. Listing the specific technologies ` +
        `you have used, and describing one or two projects you have built and deployed, ` +
        `is the highest-impact change you can make.`;
  }

  // tier === 'none'
  return evidence
    ? `We could not find internships that match your resume yet. The roles closest to your ` +
      `profile wanted ${evidence}. Start by building one project that uses ${evidence}, ` +
      `deploy it, and describe it on your resume with the technologies named.`
    : `We could not find internships that match your resume yet. Start by naming the ` +
      `specific technologies you have used and adding one project you have built and ` +
      `deployed — most internship listings match on concrete, named skills.`;
}

const resumeFeedback = buildFeedback();
const sufficient = count >= 8;

// Honest diagnosis of WHY the list is short — "only 4 good matches exist" and
// "9 existed but 5 failed to score" are completely different situations.
const reasons = [];
if (count < 8) {
  if (scoringSummary && scoringSummary.failed > 0) {
    reasons.push(
      `${scoringSummary.failed} of ${scoringSummary.attempted} opportunities could not be scored ` +
      `(provider errors), so they were excluded rather than guessed at.`
    );
  }
  if (scoringSummary && scoringSummary.skipped_no_content > 0) {
    reasons.push(
      `${scoringSummary.skipped_no_content} discovered pages had no readable job details, ` +
      `so they were not scored or shown.`
    );
  }
  // OUR failure, owned as ours — never folded into "the page had no details".
  // A render or fetch that failed on our side is not a property of the posting.
  if (scoringSummary && scoringSummary.extraction_failed > 0) {
    reasons.push(
      `${scoringSummary.extraction_failed} postings could not be read on our side ` +
      `(a fetch or render failure, not a problem with the posting), so they were ` +
      `excluded rather than guessed at.`
    );
  }
  if (allocationSummary.below_score_floor > 0) {
    reasons.push(
      `${allocationSummary.below_score_floor} scored below the minimum fit threshold ` +
      `of ${allocationSummary.min_score} and were not padded into the results.`
    );
  }
  if (reasons.length === 0) {
    reasons.push('Too few relevant open postings were discovered for this profile.');
  }
  if (discoveryBroadening && discoveryBroadening.applied) {
    reasons.push(
      `Search was already broadened before reaching this conclusion ` +
      `(${discoveryBroadening.primary_admitted} strict matches, ` +
      `+${discoveryBroadening.broadened_admitted} after relaxing).`
    );
  }
}

// Page titles are not role titles. Scraped pages routinely yield things like
// "Rejolut is hiring Frontend Developer Intern | Cutshort" or
// "Frontend Developer Intern - Acme Corp | LinkedIn". Strip the site furniture
// so the student sees the role. Falls back to the original when stripping
// would leave nothing.
function cleanRoleTitle(raw, company) {
  let t = typeof raw === 'string' ? raw.trim() : '';
  if (!t) return null;
  const original = t;

  // "<Company> is hiring <Role>" / "<Company> is looking for <Role>"
  const hiring = t.match(/^.*?\b(?:is\s+)?(?:hiring|looking for|seeks|recruiting)\s+(?:an?\s+)?(.+)$/i);
  if (hiring && hiring[1]) t = hiring[1].trim();

  // Trailing site furniture after | or · or — or -
  t = t.split(/\s+[|·•]\s+/)[0].trim();

  // "Role at Company" / "Role - Company"
  t = t.replace(/\s+(?:at|@)\s+.+$/i, '').trim();
  if (company) {
    const esc = String(company).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    t = t.replace(new RegExp(`\\s*[-–—:]\\s*${esc}\\s*$`, 'i'), '').trim();
    t = t.replace(new RegExp(`^\\s*${esc}\\s*[-–—:]\\s*`, 'i'), '').trim();
  }

  // Trailing job-board boilerplate
  t = t.replace(/\s*[-–—]\s*(job|jobs|careers?|vacancy|vacancies|internships?)\s*$/i, '').trim();
  t = t.replace(/\s*\((?:remote friendly|remote|hybrid|on-?site)\)\s*$/i, '').trim();

  if (!t || t.length < 3) return original;
  // A stripped title that lost the role word entirely is worse than the original.
  if (!/[a-z]/i.test(t)) return original;
  return t.length > 120 ? t.slice(0, 120).trim() : t;
}

// Project each opportunity onto the locked contract shape. The internal item
// accumulates duplicate spellings of the same field (applicationUrl vs
// application_url, workplaceType vs work_mode) plus run-level bookkeeping
// repeated on every row; none of that belongs in a public response.
// Anything not explicitly stated stays null — never inferred, never guessed.
function toContractShape(opp) {
  const firstOf = (...vals) => {
    for (const v of vals) {
      if (v !== undefined && v !== null && v !== '' && !(Array.isArray(v) && v.length === 0)) return v;
    }
    return null;
  };
  return {
    // Fall back to the discovered_title (the real search-result title the
    // page was found under) when extraction produced none — a titleless
    // card is not usable and must never be shown, but discovered_title is
    // genuine data, not a fabricated placeholder. Observed: FloLabs and
    // Redis came back title:null in a degraded run.
    title:            cleanRoleTitle(firstOf(opp.title, opp.discovered_title), opp.company),
    company:          firstOf(opp.company),
    description:      firstOf(opp.description),
    location:         firstOf(opp.location),
    apply_url:        firstOf(opp.apply_url, opp.application_url, opp.applicationUrl, opp.url),
    employment_type:  firstOf(opp.employment_type, opp.employmentType),
    work_mode:        firstOf(opp.work_mode, opp.workplaceType),
    salary:           firstOf(opp.salary_monthly, opp.salary),
    is_paid:          opp.is_paid === undefined ? null : opp.is_paid,
    deadline:         firstOf(opp.deadline),
    requirements:     Array.isArray(opp.requirements) ? opp.requirements
                      : (Array.isArray(opp.required_skills) ? opp.required_skills : []),
    skills:           Array.isArray(opp.skills) ? opp.skills
                      : (Array.isArray(opp.technologies) ? opp.technologies : []),
    score:            typeof opp.score === 'number' ? opp.score : null,
    reasoning:        firstOf(opp.reasoning),
    missing_requirements: Array.isArray(opp.missing_requirements) ? opp.missing_requirements : [],
    tier:             firstOf(opp.tier),
    allocation_reason: firstOf(opp.allocation_reason),
  };
}

const response = {
  // 'ok' for a full list; 'partial' when real but short; 'weak_profile' when
  // the resume itself is the limiting factor. A short list is a legitimate
  // outcome, never a padded one.
  status: count >= 8 ? 'ok' : (count >= 5 ? 'partial' : 'weak_profile'),
  result_tier: tier,
  resume_strength: resumeStrength,
  resume_feedback: resumeFeedback,
  opportunity_count: opportunities.length,
  opportunities: opportunities.map(toContractShape),
  scoring: scoringSummary,
  allocation: allocationSummary,
  discovery: discoveryBroadening
    ? {
        broadening_applied: discoveryBroadening.applied,
        primary_admitted: discoveryBroadening.primary_admitted,
        broadened_admitted: discoveryBroadening.broadened_admitted,
      }
    : null,
};

if (count < 8) {
  response.weak_profile = {
    // Whatever genuinely qualified is still returned — never an empty list
    // when real matches exist.
    returned: opportunities.length,
    target: 8,   // what a full list looks like; NOT a minimum we pad to
    reasons,
    gaps,
    gaps_note: gaps.length === 0
      ? (postings_analyzed === 0
          ? 'No successfully-scored postings were available to derive gaps from.'
          : `No skill gap appeared in at least ${MIN_GAP_FREQUENCY} of the ${postings_analyzed} scored postings, so none is reported as a pattern.`)
      : `Derived from ${postings_analyzed} successfully-scored postings.`
  };
}

return [{ json: response }];
